window.BANQUE_INFINI = {"module":"annee-2/theorique/semestre-2/pharmaco-imagerie","titre":"Pharmacologie & imagerie","sources":[{"t":"Les méthodes d'imagerie","q":"imagerie-01-methodes/quiz.html","f":"imagerie-01-methodes/fiche.html"},{"t":"Anatomie radiologique, thorax et pathologie ostéoarticulaire","q":"imagerie-02-thorax-et-osteoarticulaire/quiz.html","f":"imagerie-02-thorax-et-osteoarticulaire/fiche.html"},{"t":"Pharmacologie : notions de base","q":"pharmaco-01-notions-de-base/quiz.html","f":"pharmaco-01-notions-de-base/fiche.html"},{"t":"Pharmacocinétique : ADME et voies d'administration","q":"pharmaco-02-pharmacocinetique/quiz.html","f":"pharmaco-02-pharmacocinetique/fiche.html"},{"t":"Groupes thérapeutiques : SNC, antalgiques et cardiovasculaire","q":"pharmaco-03-groupes-therapeutiques/quiz.html","f":"pharmaco-03-groupes-therapeutiques/fiche.html"},{"t":"Cardiovasculaire, sang, respiratoire et digestif","q":"pharmaco-04-cardio-respi-digestif/quiz.html","f":"pharmaco-04-cardio-respi-digestif/fiche.html"}],"questions":[{"q":"Quelles propriétés des rayons X leur permettent de traverser les tissus ?","o":["Une longue longueur d'onde et une basse fréquence","Une haute énergie, une longueur d'onde courte et une fréquence élevée","Une nature mécanique vibratoire","Une charge électrique positive"],"r":1,"e":"Les rayons X sont un rayonnement électromagnétique de haute énergie, à longueur d'onde courte et fréquence élevée, ce qui leur permet de traverser les matériaux en étant partiellement bloqués.","s":0},{"q":"Que signifie le principe ALARA ?","o":["As Low As Reasonably Achievable : la meilleure image possible avec la plus faible dose","Always Look At Radiation Alerts","Average Level of Applied Radiation Absorption","As Long As Radiation Allows"],"r":0,"e":"ALARA signifie As Low As Reasonably Achievable : obtenir la meilleure image possible avec la plus faible dose de rayonnement.","s":0},{"q":"Qu'est-ce qui caractérise un effet déterministe du rayonnement ?","o":["Il n'a pas de seuil et augmente la probabilité","Il dépend de la dose, possède un seuil et suit généralement une dose élevée sur une courte période","Il est lié à la dose cumulée sur la vie","Il est toujours cancérigène"],"r":1,"e":"Les effets déterministes dépendent de la dose, ont un seuil, et dépendent généralement d'une dose élevée sur une courte période : érythème, brûlures, cataractes.","s":0},{"q":"Quels effets sont associés à la dose cumulée au long de la vie ?","o":["Les effets déterministes","Les effets stochastiques, sans seuil, comme le cancer et les altérations génétiques","Les brûlures","Les cataractes"],"r":1,"e":"Les effets stochastiques n'ont pas de seuil, augmentent la probabilité et sont davantage associés à la dose cumulée au long de la vie : cancer et altérations génétiques.","s":0},{"q":"Quels tissus ont la sensibilité la plus élevée au rayonnement ?","o":["La peau et les muscles","La moelle osseuse et le cristallin","Les os et le cartilage","Les tendons"],"r":1,"e":"La moelle osseuse et le cristallin ont une sensibilité très élevée ; les gonades et la thyroïde une sensibilité élevée, la peau une sensibilité modérée.","s":0},{"q":"Quelle est la limite de dose efficace annuelle pour les travailleurs ?","o":["1 mSv/an","15 mSv/an","20 mSv/an","500 mSv/an"],"r":2,"e":"La dose efficace pour les travailleurs est de 20 mSv/an, contre 1 mSv/an pour le public ; la peau tolère 500 mSv/an chez les travailleurs.","s":0},{"q":"De quoi est constitué le tube à rayons X ?","o":["D'une ampoule de verre sous vide contenant une cathode négative et une anode positive","D'un aimant supraconducteur","D'un transducteur piézoélectrique","D'un détecteur numérique et d'un gantry"],"r":0,"e":"Le tube à rayons X est constitué d'une ampoule de verre maintenue sous vide, à l'intérieur de laquelle se trouvent une cathode (électrode négative) et une anode (électrode positive).","s":0},{"q":"Comment se crée le contraste sur une radiographie ?","o":["Par l'absorption différentielle : les tissus mous laissent passer davantage de rayons, les os et métaux empêchent le passage","Par l'injection systématique de produit de contraste","Par le réglage informatique post-acquisition","Par la réflexion des ondes"],"r":0,"e":"Les tissus mous comme la peau et les muscles laissent passer davantage de rayons X, tandis que les os et les métaux empêchent le passage, créant le contraste dans l'image.","s":0},{"q":"Comment apparaît une structure très dense sur une radiographie ?","o":["Noire","Gris moyen","Plus claire, gris clair à blanc","Elle n'apparaît pas"],"r":2,"e":"Plus c'est dense, plus le rayonnement est absorbé, moins il arrive au détecteur : l'image apparaît plus claire, gris clair à blanc pour l'os, blanc pour le métal.","s":0},{"q":"Comment apparaissent les champs pulmonaires sur une radiographie du thorax ?","o":["Blancs","Noirs ou très sombres, car l'air est de basse densité","Gris clair","Gris moyen"],"r":1,"e":"L'air des poumons est de basse densité : les champs pulmonaires apparaissent noirs ou très sombres.","s":0},{"q":"Quelle est la base technologique de la tomodensitométrie ?","o":["Un champ magnétique fort","Le rayonnement X, avec des algorithmes complexes et des systèmes informatiques","Les ultrasons","Les radio-isotopes"],"r":1,"e":"La base de la TDM est le rayonnement X, semblable à la radiologie conventionnelle, en recourant à des algorithmes complexes et à des systèmes informatiques.","s":0},{"q":"Qui a développé la méthode d'isolement de l'atténuation du rayonnement associée à des tons de gris ?","o":["Röntgen","Hounsfield","Doppler","Tesla"],"r":1,"e":"Hounsfield a développé une méthode capable d'isoler l'atténuation du rayonnement et de l'associer à différents tons de gris.","s":0},{"q":"Quelle est la valeur de l'eau sur l'échelle de Hounsfield ?","o":["−1000","0","+100","+1000"],"r":1,"e":"Sur l'échelle de Hounsfield, l'eau vaut 0, l'air −1000 et l'os compact environ +1000.","s":0},{"q":"Où se trouvent les détecteurs sur un appareil de TDM ?","o":["Du même côté que l'ampoule","Du côté opposé à l'ampoule","Sous la table d'examen uniquement","Dans la console de l'opérateur"],"r":1,"e":"Du côté opposé à l'ampoule se trouvent les détecteurs, qui captent les rayons X ayant traversé le corps.","s":0},{"q":"Sur quelle base technologique repose l'IRM ?","o":["Le rayonnement ionisant","Un champ magnétique fort, des ondes radio et un gradient de champ","Les ultrasons de haute fréquence","Les rayons gamma"],"r":1,"e":"La base de l'IRM n'est pas le rayonnement ionisant mais un champ magnétique fort, des ondes radio et un gradient de champ.","s":0},{"q":"De quel atome provient presque exclusivement le signal en IRM ?","o":["Le carbone","L'oxygène","L'hydrogène","Le sodium"],"r":2,"e":"Les images de RM résultent presque exclusivement des atomes d'hydrogène, dont le noyau est constitué d'un seul proton, abondants dans l'eau et la graisse.","s":0},{"q":"Quelle particularité a le noyau de l'hydrogène ?","o":["Il ne possède pas de neutrons","Il possède deux protons","Il est dépourvu de proton","Il est électriquement neutre"],"r":0,"e":"Tous les noyaux sont constitués de protons et de neutrons, à l'exception de l'hydrogène qui ne possède pas de neutrons.","s":0},{"q":"Comment s'appelle le mouvement des protons dans le champ magnétique ?","o":["La relaxation","La précession, dont la fréquence est d'autant plus grande que le champ est fort","La diffusion","L'écho"],"r":1,"e":"Les protons ont un mouvement appelé précession, dont la fréquence varie avec le champ magnétique, étant d'autant plus grande que celui-ci est fort.","s":0},{"q":"Que mesure le temps T1 en IRM ?","o":["Le temps de retour à l'aimantation longitudinale","Le temps de retour à l'aimantation transversale","Le temps de répétition","Le temps d'écho"],"r":0,"e":"T1 est le temps de retour à l'aimantation longitudinale ; T2 est le temps de retour à l'aimantation transversale.","s":0},{"q":"Quelle intensité de champ constitue le standard clinique le plus utilisé ?","o":["0,5 T","1,5 T","3,0 T","7,0 T"],"r":1,"e":"1,5 T est le standard clinique le plus utilisé : excellent équilibre entre qualité d'image, temps d'examen et coût.","s":0},{"q":"Dans quel cas indique-t-on une IRM à champ ouvert de bas champ ?","o":["Pour les examens fonctionnels détaillés","En cas de claustrophobie sévère ou d'obésité","Pour les urgences neurologiques","Pour l'angiographie"],"r":1,"e":"Le bas champ (< 1 T, 0,2-0,5 T) est courant dans les RM ouvertes, indiqué en cas de claustrophobie sévère ou d'obésité, avec une moindre résolution et un temps d'acquisition plus long.","s":0},{"q":"Combien vaut 1 Tesla en Gauss ?","o":["100 Gauss","1 000 Gauss","10 000 Gauss","100 000 Gauss"],"r":2,"e":"1 T = 10 000 Gauss.","s":0},{"q":"Quel examen est présenté comme le meilleur pour identifier une compression nerveuse par hernie discale ?","o":["La radiographie","La TDM","L'IRM","L'échographie"],"r":2,"e":"L'IRM est le meilleur examen pour identifier une compression de nerfs par hernie discale ; elle est aussi précise pour la sténose du canal vertébral.","s":0},{"q":"Quelle séquence d'IRM permet le diagnostic précoce d'un AVC ischémique ?","o":["Le T1","Le DWI/ADC","L'angio-RM","Le STIR"],"r":1,"e":"Le diagnostic précoce de l'AVC ischémique se fait avec les séquences DWI/ADC.","s":0},{"q":"Quelle est la fréquence des ondes émises par un transducteur d'échographie ?","o":["16 à 20 Hz","1 à 15 MHz","50 à 100 MHz","20 à 200 kHz"],"r":1,"e":"Un transducteur émet des ondes ultrasonores de 1 à 15 MHz à l'intérieur du corps.","s":0},{"q":"Quels sont les cinq profils de caractérisation d'une image échographique ?","o":["Topographie, morphologie, dimension, échogénicité et échostructure","T1, T2, FLAIR, DWI et STIR","Densité, contraste, résolution, netteté et bruit","Axial, coronal, sagittal, oblique et 3D"],"r":0,"e":"La caractérisation échographique repose sur cinq profils : topographie, morphologie, dimension, échogénicité et échostructure.","s":0},{"q":"Comment apparaît une structure anéchogène ?","o":["Blanc brillant","Noire, sans échos — comme l'urine ou un kyste","Gris foncé","De même teinte que le voisinage"],"r":1,"e":"Anéchogène signifie sans échos : la structure apparaît noire, comme les liquides — urine, kystes.","s":0},{"q":"Comment apparaissent les calculs, l'os et la graisse en échographie ?","o":["Anéchogènes","Hypoéchogènes","Isoéchogènes","Hyperéchogènes, blanc brillant"],"r":3,"e":"Hyperéchogène signifie beaucoup d'échos : la structure apparaît blanc brillant, comme les calculs, l'os et la graisse.","s":0},{"q":"Que peut indiquer une échostructure hétérogène ?","o":["La normalité de l'organe","Une inflammation, une fibrose, une nécrose ou des tumeurs mixtes","Une absence de tissu","Un artefact systématique"],"r":1,"e":"Une échostructure hétérogène présente des variations d'échogénicité et peut indiquer inflammation, fibrose, nécrose ou tumeurs mixtes : abcès, tumeurs malignes, stéatose avancée.","s":0},{"q":"Quelles sont les contre-indications de l'IRM ?","o":["La grossesse et l'insuffisance rénale","Le pacemaker, les implants métalliques et la claustrophobie","Aucune contre-indication significative","L'obésité uniquement"],"r":1,"e":"Les contre-indications de l'IRM sont le pacemaker, les implants métalliques et la claustrophobie ; la TDM, elle, est contre-indiquée en grossesse et en insuffisance rénale avec contraste.","s":0},{"q":"Un effet stochastique du rayonnement se caractérise par :","o":["L'existence d'un seuil","L'absence de seuil : le rayonnement augmente seulement la probabilité de survenue","Une survenue immédiate","Une dépendance à une dose élevée sur courte période"],"r":1,"e":"Cancers et altérations génétiques sont liés à la dose cumulée au long de la vie. Les effets déterministes — érythème, brûlures, cataractes — ont au contraire un seuil.","s":0},{"q":"La limite de dose au cristallin pour le public est de :","o":["1 mSv/an","15 mSv/an","20 mSv/an","50 mSv/an"],"r":1,"e":"Elle est de 20 mSv/an pour les travailleurs. Pour la peau, les limites sont de 500 mSv/an chez les travailleurs contre 50 mSv/an pour le public.","s":0},{"q":"La limite de dose efficace annuelle pour le public est de :","o":["1 mSv","15 mSv","20 mSv","50 mSv"],"r":0,"e":"Elle est vingt fois plus élevée pour les travailleurs exposés, soit 20 mSv par an, ce qui suppose une surveillance dosimétrique individuelle.","s":0},{"q":"La thyroïde est un organe de sensibilité élevée au rayonnement, particulièrement :","o":["Chez la personne âgée","Chez l'enfant","Chez la femme enceinte","Chez l'homme adulte"],"r":1,"e":"Moelle osseuse et cristallin présentent une sensibilité très élevée ; gonades et thyroïde une sensibilité élevée ; la peau une sensibilité modérée.","s":0},{"q":"Les effets biologiques du rayonnement ionisant peuvent provoquer :","o":["Des dommages à l'ADN, la mort cellulaire ou des mutations","Uniquement des brûlures","Uniquement des cancers","Aucun effet en dessous de 20 mSv"],"r":0,"e":"C'est cette possibilité de lésion de l'ADN qui fonde à la fois les effets déterministes, à seuil, et les effets stochastiques, sans seuil.","s":0},{"q":"Dans le tube à rayons X, la cathode est :","o":["L'électrode positive","L'électrode négative","Le détecteur","Le filtre"],"r":1,"e":"L'anode est l'électrode positive. L'ensemble est enfermé dans une ampoule de verre maintenue sous vide.","s":0},{"q":"Sur une radiographie, la graisse apparaît :","o":["Noire comme l'air","En gris très foncé, densité légèrement supérieure à celle de l'air","En gris moyen comme les tissus mous","En gris clair comme l'os"],"r":1,"e":"L'échelle va du plus sombre au plus clair : air, graisse, eau et tissus mous, os, métal — c'est l'ordre de densité croissante.","s":0},{"q":"Sur une radiographie du thorax, le cœur et les vaisseaux apparaissent :","o":["Noirs","Gris moyen, comme l'eau et les tissus mous","Gris clair","Blancs"],"r":1,"e":"Les champs pulmonaires, remplis d'air, apparaissent sombres ; les côtes et le rachis en gris clair, du fait de leur forte densité.","s":0},{"q":"En tomodensitométrie, ce qui tourne autour du patient est :","o":["Le détecteur seul","L'ampoule, les détecteurs opposés captant le rayonnement atténué","La table d'examen","L'aimant"],"r":1,"e":"Hounsfield a isolé l'atténuation du rayonnement pour l'associer à des tons de gris, ce qui a rendu possible l'imagerie en coupes.","s":0},{"q":"Sur l'échelle de Hounsfield, l'air correspond à :","o":["−1000","−100","0","+1000"],"r":0,"e":"L'eau vaut 0 par définition et l'os compact environ +1000. Cette échelle quantifie l'atténuation et permet de caractériser objectivement un tissu.","s":0},{"q":"La tomodensitométrie produit des images :","o":["Uniquement axiales","Multiplanaires : axiales, coronales et sagittales","Uniquement sagittales","En trois dimensions uniquement"],"r":1,"e":"Au thorax, deux fenêtres d'analyse sont utilisées : la fenêtre de parenchyme pulmonaire et la fenêtre de médiastin.","s":0},{"q":"L'IRM repose sur :","o":["Des rayons X de faible énergie","Un champ magnétique fort, des ondes radio et un gradient de champ, sans rayonnement ionisant","Des ultrasons","Des isotopes radioactifs"],"r":1,"e":"L'absence de rayonnement ionisant en fait une technique privilégiée chez l'enfant et la femme enceinte, sous réserve des contre-indications magnétiques.","s":0},{"q":"Le noyau de l'hydrogène, source du signal IRM, est constitué :","o":["D'un proton et d'un neutron","D'un seul proton, sans neutron","De deux protons","D'un électron"],"r":1,"e":"Cette particularité lui confère les propriétés magnétiques exploitées. L'hydrogène est très abondant dans l'eau et la graisse, donc dans tous les tissus.","s":0},{"q":"Le mouvement des protons placés dans un champ magnétique s'appelle :","o":["La relaxation","La précession","L'excitation","La saturation"],"r":1,"e":"Les quatre étapes de l'IRM : alignement dans le champ avec précession, impulsion de radiofréquence excitatrice, relaxation, puis traitement des données.","s":0},{"q":"Le temps T2 en IRM mesure :","o":["Le retour à l'aimantation longitudinale","Le retour à l'aimantation transversale","La vitesse de précession","L'intensité du champ"],"r":1,"e":"Le T1 correspond au retour à l'aimantation longitudinale. Ces deux constantes, propres à chaque tissu, sont à l'origine du contraste en IRM.","s":0},{"q":"Une IRM de 3 Tesla est qualifiée de :","o":["Bas champ","Standard clinique","Haut champ","Champ ouvert"],"r":2,"e":"1,5 T constitue le standard clinique le plus utilisé ; en dessous de 1 T, on parle de champ ouvert, indiqué en cas de claustrophobie ou d'obésité.","s":0},{"q":"L'IRM à champ ouvert de bas champ est indiquée notamment en cas :","o":["De claustrophobie ou d'obésité","D'urgence vitale","De port de pacemaker","De grossesse"],"r":0,"e":"Sa géométrie ouverte améliore la tolérance, au prix d'une résolution et d'un rapport signal sur bruit inférieurs à ceux du haut champ.","s":0},{"q":"Le transducteur d'échographie émet des ondes de fréquence :","o":["1 à 15 MHz","1 à 15 kHz","20 à 20 000 Hz","1 à 15 GHz"],"r":0,"e":"Le temps de retour et l'intensité de l'écho génèrent l'image. La méthode est sûre, non invasive et dépourvue de rayonnement ionisant.","s":0},{"q":"Parmi les cinq profils de caractérisation d'une image échographique figure :","o":["La densité","L'échostructure","La radio-opacité","L'atténuation en unités Hounsfield"],"r":1,"e":"Les cinq profils sont : topographie, morphologie, dimension, échogénicité et échostructure.","s":0},{"q":"Une structure hypoéchogène apparaît :","o":["Noire","Gris foncé, comme les muscles","Blanche brillante","De la même teinte que le voisinage"],"r":1,"e":"Anéchogène correspond au noir des liquides et des kystes ; isoéchogène à la teinte du voisinage, comme le foie ou la rate normaux ; hyperéchogène au blanc brillant des calculs, de l'os et de la graisse.","s":0},{"q":"Comment les images d'imagerie sont-elles présentées ?","o":["Comme si le médecin était derrière le patient","Comme si le médecin était face au patient","Toujours en vue de profil","Selon le choix du radiologue"],"r":1,"e":"Dans les examens d'imagerie, les images sont présentées comme si le médecin était face au patient : la droite du patient apparaît à gauche de l'image.","s":1},{"q":"Que signifie le A de la méthode ABCDE de lecture d'une RX de thorax ?","o":["Abdomen","Airway, les voies aériennes","Aorte","Artères"],"r":1,"e":"ABCDE = Airway (voies aériennes), Bone (os et tissus mous), Cardiac (cœur et médiastin), Diaphragm, Everything (poumons, plèvre et dispositifs).","s":1},{"q":"Que désigne le E de la méthode ABCDE ?","o":["Épanchement","Everything : poumons, plèvre et dispositifs","Œsophage","Emphysème"],"r":1,"e":"Le E signifie Everything : poumons, plèvre et dispositifs comme les tubes et prothèses.","s":1},{"q":"Quelles sont les deux fenêtres d'évaluation d'une TDM thoracique ?","o":["Fenêtre osseuse et fenêtre cutanée","Fenêtre de parenchyme pulmonaire et fenêtre de médiastin","Fenêtre T1 et fenêtre T2","Fenêtre antérieure et postérieure"],"r":1,"e":"Les images de TDM thoracique sont évaluées dans deux fenêtres : la fenêtre de parenchyme pulmonaire pour l'étude du poumon et la fenêtre de médiastin pour le médiastin et la vascularisation.","s":1},{"q":"Pourquoi l'échographie n'est-elle pas un examen de première ligne au thorax ?","o":["À cause du rayonnement","À cause des barrières acoustiques osseuse et aérienne : absorption par l'os et réflexion totale par le poumon aéré","Parce qu'elle est trop coûteuse","Parce qu'elle est contre-indiquée"],"r":1,"e":"L'évaluation échographique du thorax est conditionnée par les barrières acoustiques osseuse et aérienne ; seuls l'espace pleural et le parenchyme sous-pleural restent accessibles.","s":1},{"q":"Quelle est la cause principale de la BPCO ?","o":["Le tabagisme","L'exposition à l'amiante","Les infections répétées","Une maladie auto-immune"],"r":0,"e":"La cause principale de la BPCO est le tabagisme ; elle englobe la bronchite chronique et l'emphysème pulmonaire.","s":1},{"q":"Que peut montrer la radiographie du thorax d'un patient avec BPCO ?","o":["Toujours une hyperinflation marquée","Elle peut être NORMALE","Toujours une condensation lobaire","Toujours une cavitation"],"r":1,"e":"Le cours insiste : la radiographie du thorax d'un patient avec BPCO peut être normale.","s":1},{"q":"Quels signes radiographiques évoquent une hyperinflation pulmonaire ?","o":["Augmentation de l'espace rétrosternal et augmentation du nombre de côtes dans les champs pulmonaires","Condensation lobaire et bronchogramme aérien","Opacités en verre dépoli","Épanchement pleural"],"r":0,"e":"L'hyperinflation pulmonaire se traduit par une augmentation de l'espace rétrosternal et une augmentation du nombre de côtes visibles dans les champs pulmonaires.","s":1},{"q":"Comment définit-on les bronchectasies ?","o":["Un rétrécissement des bronches","Une dilatation anormale et permanente des bronches","Une inflammation des alvéoles","Une fibrose interstitielle"],"r":1,"e":"Les bronchectasies sont caractérisées par la dilatation anormale et permanente des bronches, par affaiblissement et atteinte de leurs parois.","s":1},{"q":"Quel signe TDM est classique des bronchectasies ?","o":["Le verre dépoli","Le signe de l'arbre en bourgeons","Les kystes en rayon de miel","Le bronchogramme aérien"],"r":1,"e":"Le signe de l'arbre en bourgeons est caractéristique : les voies aériennes dilatées apparaissent comme des branches d'un arbre.","s":1},{"q":"Sur quoi repose principalement le diagnostic de l'asthme ?","o":["Sur la TDM thoracique","Sur la clinique et les tests de fonction respiratoire","Sur la radiographie du thorax","Sur l'IRM"],"r":1,"e":"Le diagnostic de l'asthme est principalement clinique, basé sur les symptômes et les tests de fonction respiratoire ; l'imagerie sert à chercher des complications ou à exclure d'autres maladies.","s":1},{"q":"Quels signes TDM caractérisent la fibrose pulmonaire idiopathique ?","o":["Des opacités en verre dépoli et des kystes en rayon de miel","Une cavitation","Un signe de l'arbre en bourgeons","Une condensation lobaire homogène"],"r":0,"e":"Le diagnostic se fait par TDM : opacités en verre dépoli et kystes en rayon de miel.","s":1},{"q":"Quel pourcentage de patients survit plus de 5 ans après le diagnostic de fibrose pulmonaire idiopathique ?","o":["10 %","30 %","60 %","90 %"],"r":1,"e":"Les cicatrices gênent les échanges gazeux, causant une dyspnée, et seulement 30 % survivent plus de 5 ans après le diagnostic.","s":1},{"q":"Quelles maladies sont causées par l'inhalation de poussière ?","o":["Les pneumoconioses : silicose, asbestose et bérylliose","La sarcoïdose","La fibrose idiopathique","Les bronchectasies"],"r":0,"e":"Les pneumoconioses sont causées par l'inhalation de poussière : silicose, asbestose et bérylliose.","s":1},{"q":"Qu'est-ce qui distingue la pneumonie lobaire de la bronchopneumonie ?","o":["La pneumonie lobaire donne une condensation homogène d'un lobe entier aux bords bien définis, la bronchopneumonie des infiltrats petits, multiples et irréguliers","La pneumonie lobaire est virale","La bronchopneumonie touche un seul lobe","Il n'y a pas de différence radiologique"],"r":0,"e":"La pneumonie lobaire affecte un seul lobe de manière homogène avec des bords bien définis ; la bronchopneumonie affecte de multiples segments de façon diffuse, avec des infiltrats petits et irréguliers.","s":1},{"q":"Quel signe radiologique accompagne la condensation lobaire ?","o":["Le signe de l'arbre en bourgeons","Le bronchogramme aérien","Le double contour","Les kystes en rayon de miel"],"r":1,"e":"La pneumonie lobaire s'accompagne classiquement d'un bronchogramme aérien au sein de la condensation.","s":1},{"q":"Quel profil TDM caractérise la pneumonie à COVID-19 ?","o":["Une cavitation unilatérale","Un profil en verre dépoli de distribution bilatérale","Une condensation lobaire","Un épanchement pleural massif"],"r":1,"e":"La pneumonie COVID-19 se caractérise par un profil en verre dépoli de distribution bilatérale.","s":1},{"q":"Quelle bactérie cause la tuberculose ?","o":["Escherichia coli","Mycobacterium tuberculosis","Proteus mirabilis","Streptococcus pneumoniae"],"r":1,"e":"La tuberculose est causée par Mycobacterium tuberculosis ; l'inhalation d'air contenant des bacilles les fait se déposer dans les poumons.","s":1},{"q":"Quel signe caractérise la tuberculose active à l'imagerie ?","o":["La cavitation, avec de multiples lésions excavées","Le verre dépoli isolé","Les ostéophytes","Le pneumothorax"],"r":0,"e":"La tuberculose active se traduit par une cavitation avec de multiples lésions excavées, des condensations diffuses et des infiltrats alvéolaires ou interstitiels.","s":1},{"q":"À quoi est fréquemment associé le mésothéliome pleural ?","o":["Au tabagisme","À l'exposition à l'amiante","Aux infections répétées","À l'inhalation de silice"],"r":1,"e":"Le mésothéliome est un type rare de tumeur qui prend naissance dans les cellules de la plèvre et est fréquemment associé à l'exposition à l'amiante.","s":1},{"q":"Qu'est-ce qu'un pneumothorax ?","o":["Une accumulation de liquide dans la plèvre","La présence d'air dans la cavité pleurale, avec poumon affaissé","Une dilatation des bronches","Une fibrose de l'interstitium"],"r":1,"e":"Le pneumothorax est la présence d'air dans la cavité pleurale, entraînant un poumon affaissé ; il peut être traumatique, secondaire à une maladie pulmonaire ou spontané.","s":1},{"q":"Comment apparaissent les tendons en pondération T1 ?","o":["Hyper-intenses, très clairs","Hypo-intenses, gris foncé, car le collagène contient peu d'eau","Iso-intenses, gris moyen","Sans signal détectable"],"r":1,"e":"En T1, les tendons sont hypo-intenses, gris foncé, car ils sont constitués de collagène qui contient peu d'eau.","s":1},{"q":"Comment apparaissent les muscles en séquence STIR ?","o":["Hypo-intenses","Hyper-intenses, avec un signal élevé","Iso-intenses gris foncé","Sans signal"],"r":1,"e":"En STIR, les muscles sont hyper-intenses ; en T1 ils sont iso-intenses, gris.","s":1},{"q":"Pourquoi les ligaments sont-ils difficiles à visualiser en radiographie ?","o":["À cause de leur faible densité, sauf en cas de calcification","Parce qu'ils absorbent trop les rayons X","Parce qu'ils sont trop profonds","Parce qu'ils sont mobiles"],"r":0,"e":"Les ligaments sont de faible densité, semblables aux tendons, donc difficiles à visualiser en radiographie sauf en cas de calcification ou de lésion associée.","s":1},{"q":"Quels sont les signes radiographiques de la polyarthrite rhumatoïde ?","o":["Ostéophytes marginaux et sclérose sous-chondrale","Réduction de l'interligne, érosions marginales, ostéopénie péri-articulaire, déformations, subluxations et ankylose","Bords saillants et préservation de l'interligne","Aspect en bambou"],"r":1,"e":"Les six signes en RX sont : réduction de l'interligne, érosions osseuses marginales, ostéopénie péri-articulaire, déformations articulaires, subluxations et instabilités, fusion osseuse (ankylose).","s":1},{"q":"Quel est l'apport spécifique de l'IRM dans la polyarthrite rhumatoïde ?","o":["Elle mesure la densité minérale osseuse","Elle détecte les lésions précoces avant la radiographie et évalue l'activité inflammatoire actuelle","Elle remplace la biologie","Elle identifie les cristaux d'urate"],"r":1,"e":"L'IRM détecte les lésions précoces avant les altérations visibles sur la radiographie, évalue l'activité inflammatoire actuelle pour guider le traitement, et montre synovite, ténosynovite, œdème osseux et érosions précoces.","s":1},{"q":"Quels sont les quatre signes radiographiques de l'arthrose ?","o":["Diminution de l'interligne, ostéophytes marginaux, sclérose sous-chondrale et déformation articulaire","Érosions marginales, ostéopénie, ankylose et subluxation","Verre dépoli, cavitation, condensation et épanchement","Tophus, double contour, bords saillants et chondrocalcinose"],"r":0,"e":"L'arthrose se traduit en RX par une diminution de l'interligne articulaire, des ostéophytes marginaux, une sclérose sous-chondrale et une déformation articulaire.","s":1},{"q":"Quel examen est l'étalon-or du diagnostic de l'ostéoporose ?","o":["La radiographie","La TDM","La densitométrie osseuse (DEXA)","L'IRM"],"r":2,"e":"La densitométrie osseuse (DEXA) est l'étalon-or ; elle mesure la DMO au rachis lombaire, au col du fémur et au poignet. L'IRM, elle, n'évalue pas la DMO.","s":1},{"q":"Quel T-score définit l'ostéoporose ?","o":["T ≥ −1,0","T entre −1,0 et −2,5","T ≤ −2,5","T ≤ −1,5"],"r":2,"e":"Normal : T ≥ −1,0 ; ostéopénie : entre −1,0 et −2,5 ; ostéoporose : T ≤ −2,5 ; ostéoporose sévère : T ≤ −2,5 avec fracture par fragilité.","s":1},{"q":"Pourquoi le ménisque médial est-il plus souvent lésé que le latéral ?","o":["Parce qu'il est plus fixe, tandis que le latéral est plus mobile","Parce qu'il est plus épais","Parce qu'il est moins vascularisé","Parce qu'il supporte moins de charge"],"r":0,"e":"Le ménisque médial est plus fixe, donc plus sujet aux lésions ; le ménisque latéral est plus mobile et ses lésions sont moins fréquentes.","s":1},{"q":"Le plan coronal sépare :","o":["La droite et la gauche","L'avant et l'arrière","Le haut et le bas","Le dedans et le dehors"],"r":1,"e":"Le plan sagittal sépare droite et gauche, le plan axial ou transversal sépare haut et bas.","s":1},{"q":"Le B de la méthode ABCDE correspond à l'analyse :","o":["Des voies aériennes","Des os et des tissus mous : côtes, rachis, clavicules, parties molles","Du cœur et du médiastin","Du diaphragme"],"r":1,"e":"A pour les voies aériennes, C pour le cœur et le médiastin, D pour le diaphragme, E pour les poumons, la plèvre et les dispositifs.","s":1},{"q":"Le C de la méthode ABCDE conduit à repérer notamment :","o":["La trachée et les bronches souches","L'arc de l'aorte, la veine cave supérieure, le tronc pulmonaire et les cavités cardiaques","Les coupoles diaphragmatiques","Les tubes et prothèses"],"r":1,"e":"L'analyse du D porte sur les coupoles, les culs-de-sac et la position en inspiration ou en expiration.","s":1},{"q":"Au protocole IRM du thorax, la séquence T2 sert notamment à :","o":["Étudier les structures anatomiques","Différencier lésions kystiques et solides et détecter précocement inflammations et œdèmes","Évaluer la fonction ventriculaire","Saturer la graisse"],"r":1,"e":"Le T1 explore les structures anatomiques, la séquence Ciné la fonction ventriculaire et le flux, les séquences STIR et FS saturent la graisse.","s":1},{"q":"L'échographie thoracique reste accessible à :","o":["L'ensemble du parenchyme","L'espace pleural et le parenchyme sous-pleural","Le médiastin uniquement","Les bronches proximales"],"r":1,"e":"Les barrières acoustiques limitent l'exploration : l'os absorbe les ultrasons et le poumon aéré les réfléchit totalement.","s":1},{"q":"Les six grandes catégories de pathologies thoraciques retenues par le cours comprennent :","o":["Obstructives, restrictives, infectieuses, néoplasiques, vasculaires et pleurales","Aiguës, chroniques, congénitales, acquises, tumorales et traumatiques","Hautes, basses, unilatérales, bilatérales, diffuses et localisées","Médicales, chirurgicales, urgentes, différées, bénignes et malignes"],"r":0,"e":"Les maladies obstructives regroupent BPCO, asthme et bronchectasies, toutes caractérisées par une gêne à l'écoulement de l'air.","s":1},{"q":"La BPCO recouvre deux entités :","o":["Asthme et emphysème","Bronchite chronique et emphysème pulmonaire","Bronchectasies et fibrose","Pneumonie et pleurésie"],"r":1,"e":"La bronchite chronique associe toux persistante et production excessive de mucus ; l'emphysème correspond à des dommages alvéolaires gênant les échanges gazeux.","s":1},{"q":"Parmi les signes radiographiques de la BPCO, le cours cite :","o":["Une augmentation de l'espace rétrosternal et du nombre de côtes visibles dans les champs pulmonaires","Une condensation lobaire","Un épanchement pleural","Des opacités en verre dépoli"],"r":0,"e":"Ces signes traduisent l'hyperinflation. Le cours souligne un point clé : la radiographie peut être parfaitement normale dans la BPCO.","s":1},{"q":"Le signe de l'arbre en bourgeons est caractéristique en TDM :","o":["De la fibrose pulmonaire","Des bronchectasies","De l'emphysème","Du pneumothorax"],"r":1,"e":"S'y associent la dilatation des voies aériennes et l'épaississement des parois bronchiques. Le diagnostic de bronchectasies repose essentiellement sur la TDM.","s":1},{"q":"Les opacités en verre dépoli associées à des kystes en rayon de miel évoquent :","o":["Une pneumonie lobaire","Une fibrose pulmonaire idiopathique","Une tuberculose","Un mésothéliome"],"r":1,"e":"Le pronostic est sévère : seulement 30 % des patients survivent plus de cinq ans après le diagnostic.","s":1},{"q":"La pneumonie lobaire se distingue de la bronchopneumonie par :","o":["Une condensation homogène d'un lobe entier, aux bords bien définis, avec bronchogramme aérien","Des infiltrats petits, multiples et irréguliers","Une atteinte pleurale","Une cavitation"],"r":0,"e":"La bronchopneumonie donne au contraire des infiltrats petits, multiples, irréguliers et diffus, sans systématisation lobaire.","s":1},{"q":"La pneumonie à COVID-19 se caractérise en TDM par :","o":["Une condensation lobaire unique","Des opacités en verre dépoli bilatérales","Une cavitation apicale","Un épanchement pleural massif"],"r":1,"e":"Cette distribution bilatérale et périphérique est assez évocatrice pour avoir servi d'appoint diagnostique pendant la pandémie.","s":1},{"q":"La tuberculose active se reconnaît à l'imagerie notamment par :","o":["Une cavitation","Un pneumothorax","Un verre dépoli isolé","Des ostéophytes"],"r":0,"e":"S'y ajoutent des condensations diffuses et des infiltrats alvéolaires ou interstitiels. L'agent en cause est Mycobacterium tuberculosis.","s":1},{"q":"Le mésothéliome pleural est fréquemment associé à :","o":["Au tabagisme","À l'exposition à l'amiante","À la tuberculose","Aux infections répétées"],"r":1,"e":"Le délai entre exposition et maladie peut dépasser trente ans, ce qui explique que des cas soient encore diagnostiqués aujourd'hui.","s":1},{"q":"En pondération T1, la corticale osseuse apparaît :","o":["Hypo-intense","Iso-intense","Hyper-intense","Invisible"],"r":0,"e":"La moelle osseuse est iso-intense et claire, les muscles iso-intenses, et les tendons, ligaments et ménisques hypo-intenses.","s":1},{"q":"En séquence STIR, le cartilage apparaît :","o":["Hypo-intense","Iso-intense, gris clair","Hyper-intense","Noir"],"r":1,"e":"Les muscles sont hyper-intenses en STIR. Cette séquence, qui sature la graisse, fait ressortir l'œdème et l'inflammation.","s":1},{"q":"En imagerie musculo-squelettique, la tomodensitométrie :","o":["Est supérieure à l'IRM pour les tissus mous","Distingue mieux les tissus mous que la radiographie, mais reste inférieure à l'IRM","Ne montre que l'os","Est l'étalon-or des ménisques"],"r":1,"e":"La radiographie ne montre bien que l'os ; l'IRM est l'étalon-or pour tendons, ligaments, ménisques et cartilage.","s":1},{"q":"Les ligaments sont difficiles à visualiser en radiographie parce qu'ils :","o":["Sont trop petits","Ont une densité voisine de celle des autres tissus mous","Sont trop mobiles","Absorbent tous les rayons X"],"r":1,"e":"Sans différence d'absorption, pas de contraste : la radiographie ne peut distinguer des structures de densité comparable.","s":1},{"q":"Parmi les signes radiographiques de la polyarthrite rhumatoïde, le cours cite :","o":["Des ostéophytes marginaux","Des érosions marginales et une ostéopénie péri-articulaire","Une sclérose sous-chondrale","Des syndesmophytes"],"r":1,"e":"S'y ajoutent la réduction de l'interligne, les déformations, les subluxations et l'ankylose. Les ostéophytes et la sclérose évoquent au contraire l'arthrose.","s":1},{"q":"L'apport spécifique de l'IRM dans la polyarthrite rhumatoïde est de détecter :","o":["Les déformations tardives","Les lésions précoces : synovite, ténosynovite, œdème osseux et érosions débutantes","Les ankyloses","Les luxations"],"r":1,"e":"Cette détection précoce permet d'agir avant les destructions irréversibles visibles en radiographie.","s":1},{"q":"De quels mots vient le terme pharmacologie ?","o":["Pharmacon et logos","Pharmakos et graphein","Pharma et logia","Pharmacon et therapeia"],"r":0,"e":"Pharmacon + logos = pharmacologie, science qui étudie les médicaments.","s":2},{"q":"Quelle discipline étudie l'influence des facteurs génétiques sur la pharmacodynamie et la pharmacocinétique ?","o":["La pharmacognosie","La pharmacogénétique","La pharmacie galénique","La toxicologie"],"r":1,"e":"La pharmacogénétique étudie l'influence des facteurs génétiques sur la pharmacodynamie, la pharmacocinétique et la toxicologie, ou les modifications induites par les médicaments dans le matériel génétique.","s":2},{"q":"Quelle discipline étudie les médicaments d'origine animale et végétale ?","o":["La pharmacognosie","La pharmacodynamie","La pharmacothérapie","La pharmacie galénique"],"r":0,"e":"La pharmacognosie étudie les médicaments d'origine animale et végétale, produits naturels utilisés comme médicaments.","s":2},{"q":"Que signifie « corps → médicament » ?","o":["La pharmacodynamie","La pharmacocinétique : absorption, distribution, métabolisation et excrétion","La toxicologie","La pharmacogénétique"],"r":1,"e":"La pharmacocinétique étudie ce que l'organisme fait au médicament : absorption, distribution, métabolisation, excrétion (ADME).","s":2},{"q":"Qu'étudie la pharmacodynamie ?","o":["Les actions pharmacologiques et leurs mécanismes, soit médicament → corps","L'absorption et l'excrétion","Les formes pharmaceutiques","La posologie"],"r":0,"e":"La pharmacodynamie étudie les actions pharmacologiques et leurs mécanismes : c'est le sens médicament → corps.","s":2},{"q":"Qu'est-ce qu'un xénobiotique en toxicologie ?","o":["Un médicament naturel","Un agent chimique ou physique étudié pour ses effets nocifs sur les organismes vivants","Un excipient","Un antidote"],"r":1,"e":"La toxicologie étudie les effets nocifs des agents chimiques ou physiques, appelés xénobiotiques, sur les organismes vivants.","s":2},{"q":"Quelle discipline s'occupe de la préparation des médicaments sous formes pharmaceutiques ?","o":["La pharmacie galénique","La pharmacothérapie","La pharmacognosie","La pharmacologie expérimentale"],"r":0,"e":"La pharmacie galénique prépare les médicaments sous des formes pharmaceutiques qui permettent leur administration aux patients.","s":2},{"q":"Quand la pharmacologie clinique peut-elle être menée chez l'humain ?","o":["Immédiatement après la synthèse du médicament","Seulement si la pharmacologie expérimentale se révèle sûre","Uniquement après la mise sur le marché","Sans condition préalable"],"r":1,"e":"La pharmacologie clinique étudie la PD, la PK et la toxicité chez l'humain, seulement si la pharmacologie expérimentale se révèle SÛRE.","s":2},{"q":"Quels deux éléments sont obligatoires en pharmacologie expérimentale comme clinique ?","o":["Le groupe contrôle et la randomisation","Le placebo et l'insu","La biodisponibilité et la demi-vie","Le consentement et le comité d'éthique"],"r":0,"e":"Le groupe contrôle et la randomisation sont tous deux obligatoires ; en l'absence de traitement d'efficacité démontrée, le groupe contrôle reçoit un placebo.","s":2},{"q":"Chez qui la phase I d'un essai clinique est-elle menée ?","o":["Chez 100-200 volontaires malades","Chez des volontaires humains sains en nombre restreint","Chez 1000-2000 patients","Après la mise sur le marché"],"r":1,"e":"La phase I est menée chez des volontaires humains sains en nombre restreint, pour évaluer préliminairement la sécurité (toxicité) et la pharmacocinétique.","s":2},{"q":"Combien de volontaires compte typiquement la phase II ?","o":["10 à 20","100 à 200","1000 à 2000","Plus de 10 000"],"r":1,"e":"La phase II porte sur des échantillons de 100-200 volontaires malades, avec une pathologie bien caractérisée pour éviter les erreurs d'interprétation.","s":2},{"q":"Que détermine-t-on principalement en phase II ?","o":["La dose létale","La relation dose/réponse, l'intervalle dose/posologie et la dose thérapeutique humaine","Le rapport risque/bénéfice à long terme","Les effets indésirables rares"],"r":1,"e":"La phase II détermine la relation dose/réponse et l'intervalle dose/posologie, stipule la dose thérapeutique humaine et évalue la sécurité à court terme.","s":2},{"q":"Combien de patients compte typiquement la phase III ?","o":["100 à 200","1000 à 2000","10 à 50","Plus de 100 000"],"r":1,"e":"La phase III implique un nombre élevé de patients : 1000 à 2000.","s":2},{"q":"Quel est l'objectif de la phase III ?","o":["Évaluer la toxicité initiale","Démontrer et confirmer le bénéfice thérapeutique par essai comparatif et établir le rapport risque/bénéfice","Surveiller après commercialisation","Étudier le métabolisme chez le volontaire sain"],"r":1,"e":"La phase III démontre ou confirme le bénéfice thérapeutique par essai comparatif avec les thérapeutiques alternatives, et permet d'établir le rapport risque/bénéfice : évaluation de la valeur thérapeutique relative et globale.","s":2},{"q":"À quoi correspond la phase IV ?","o":["À la surveillance après mise sur le marché, avec la pharmacovigilance","Aux essais précliniques","À la détermination de la dose létale","Au premier essai chez l'humain"],"r":0,"e":"La phase IV est menée après la mise sur le marché et l'usage à grande échelle ; elle confirme la valeur thérapeutique et repose sur la pharmacovigilance.","s":2},{"q":"Quel est l'objectif de la pharmacovigilance ?","o":["Découvrir dans les meilleurs délais les effets indésirables causés et enregistrer leurs caractéristiques","Calculer la dose de charge","Évaluer la biodisponibilité","Comparer deux molécules"],"r":0,"e":"La pharmacovigilance a pour objectif de découvrir dans les meilleurs délais les effets indésirables causés et d'enregistrer leurs caractéristiques.","s":2},{"q":"Qu'est-ce qu'un essai clinique « ouvert » ?","o":["Un essai sans groupe contrôle","Un essai dans lequel tant l'investigateur que le patient savent quelle médication est administrée","Un essai où seul le patient ignore le traitement","Un essai multicentrique"],"r":1,"e":"Dans un essai ouvert, tant l'investigateur que le patient savent quelle médication est administrée.","s":2},{"q":"Lequel de ces objectifs N'EST PAS une raison de l'insu ?","o":["Que le patient ne modifie pas son comportement","Que les professionnels ne modifient pas le régime ni ne procèdent à un suivi préférentiel","Éviter les erreurs systématiques d'évaluation","Réduire le coût de l'essai"],"r":3,"e":"Les trois raisons de l'insu concernent le comportement du patient, les modifications de régime par les soignants et les erreurs systématiques d'évaluation.","s":2},{"q":"Comment le cours définit-il le médicament ?","o":["Des agents chimiques capables de modifier les fonctions des êtres vivants","Toute substance d'origine naturelle","Un produit vendu en pharmacie","Une substance sans effet toxique"],"r":0,"e":"Le médicament est constitué d'agents chimiques capables de modifier les fonctions des êtres vivants ; c'est aussi toute substance ayant des propriétés curatives ou préventives.","s":2},{"q":"Qu'est-ce qu'un médicament étiotrope ?","o":["Un médicament agissant directement sur l'organisme du patient","Un médicament dont l'effet résulte d'une action sur les organismes pathogènes","Un médicament symptomatique","Un médicament de substitution"],"r":1,"e":"Les médicaments étiotropes agissent sur les organismes pathogènes qui infectent l'Homme ; ils n'influencent aucune activité biologique et visent à tuer ou empêcher la multiplication des micro-organismes.","s":2},{"q":"Quel exemple correspond à un médicament organotrope ?","o":["Un antibiotique","Un antifongique","Un antihypertenseur","Un antiviral"],"r":2,"e":"Les organotropes conditionnent la modification d'un paramètre biologique : antihypertenseurs, analgésiques.","s":2},{"q":"Que désigne le temps de demi-vie (t½) ?","o":["Le temps pour atteindre la concentration maximale","Le temps nécessaire pour que la concentration plasmatique se réduise à 50 %","La durée totale d'action","Le délai avant élimination complète"],"r":1,"e":"Le temps de demi-vie est le temps nécessaire pour que la concentration plasmatique du médicament se réduise à 50 %.","s":2},{"q":"Qu'est-ce que la concentration minimale efficace (CME) ?","o":["La plus basse concentration capable de produire l'effet désiré","La plus grande concentration sans effet toxique","La concentration moyenne à l'équilibre","La concentration au pic"],"r":0,"e":"La CME est la plus basse concentration capable de produire l'effet désiré ; la CMT est la plus grande concentration qui n'engendre pas d'effets toxiques.","s":2},{"q":"Un médicament qui dépasse la CME ET la CMT présente :","o":["Aucune action pharmacologique","Une action pharmacologique sans toxicité","Une action pharmacologique avec des effets toxiques visibles","Une action retardée"],"r":2,"e":"C'est le cas C du cours : le médicament a dépassé la CME donc agit, mais a aussi dépassé la CMT, d'où des effets toxiques.","s":2},{"q":"À quoi sert une dose de charge ?","o":["À maintenir une concentration à l'équilibre","À atteindre rapidement la concentration désirée en début de traitement","À réduire la toxicité","À prolonger la demi-vie"],"r":1,"e":"La dose de charge est la dose ou série de doses administrées au début du traitement afin d'atteindre rapidement la concentration désirée.","s":2},{"q":"Qu'est-ce que l'hémisynthèse ?","o":["La synthèse totale en laboratoire","Des médicaments d'origine naturelle auxquels on retire, ajoute ou substitue certains groupes chimiques","Une extraction végétale simple","Un mélange de deux principes actifs"],"r":1,"e":"L'hémisynthèse concerne les médicaments d'origine naturelle auxquels on retire, ajoute ou substitue certains groupes chimiques.","s":2},{"q":"Quelle est la différence entre bactéricide et bactériostatique ?","o":["Le bactéricide tue l'agent causal, le bactériostatique gêne sa croissance et sa multiplication","Le bactéricide est symptomatique","Le bactériostatique tue les bactéries","Il n'y a pas de différence"],"r":0,"e":"Les bactéricides entraînent la mort de l'agent causal ; les bactériostatiques gênent la croissance et la multiplication.","s":2},{"q":"Qu'est-ce que la synergie de potentialisation ?","o":["L'effet de A+B égale l'effet de A plus l'effet de B","L'effet de A+B est supérieur à la somme des effets de A et de B","L'effet de A est annulé par B","Les deux médicaments agissent sur le même récepteur en compétition"],"r":1,"e":"Dans la potentialisation, l'effet des médicaments A+B est supérieur à l'effet de A + l'effet de B ; exemple : captopril + diurétiques.","s":2},{"q":"Quel exemple illustre un antagonisme physiologique ?","o":["Acétylcholine et atropine","Glucagon et insuline sur la glycémie","Chélateurs et métaux lourds","Aspirine et paracétamol"],"r":1,"e":"L'antagonisme physiologique survient quand deux substances produisent des effets opposés sur la même fonction en agissant sur des structures différentes : glucagon et insuline sur la glycémie.","s":2},{"q":"Qu'est-ce qu'un antagoniste au sens du complexe médicament-récepteur ?","o":["Un médicament ayant affinité et activité intrinsèque","Un médicament ayant une affinité mais sans activité intrinsèque","Un médicament sans affinité","Un médicament à activité partielle"],"r":1,"e":"L'antagoniste possède une affinité — il se fixe au récepteur — mais pas d'activité intrinsèque : il ne produit pas d'effet.","s":2},{"q":"La pharmacologie spéciale se distingue de la pharmacologie générale parce qu'elle étudie :","o":["Les principes applicables à tous les médicaments","Chaque médicament en particulier","Les médicaments chez l'animal","Les formes pharmaceutiques"],"r":1,"e":"La pharmacologie générale traite des principes et concepts communs ; la spéciale entre dans le détail de chaque molécule.","s":2},{"q":"La pharmacothérapie a pour objet :","o":["La préparation des formes pharmaceutiques","La classification, la posologie et l'action thérapeutique des médicaments","Les effets nocifs des xénobiotiques","L'origine animale et végétale des médicaments"],"r":1,"e":"La pharmacie galénique s'occupe des formes pharmaceutiques, la toxicologie des effets nocifs, la pharmacognosie des produits naturels.","s":2},{"q":"Le Ginkgo biloba est cité dans le cours comme exemple relevant :","o":["De la pharmacogénétique","De la pharmacognosie","De la toxicologie","De la pharmacie galénique"],"r":1,"e":"La pharmacognosie étudie les médicaments d'origine animale et végétale, c'est-à-dire les produits naturels utilisés comme médicaments.","s":2},{"q":"La pharmacogénétique étudie notamment :","o":["Les modifications induites par les médicaments dans le matériel génétique","La biodisponibilité","Les formes retard","Les interactions alimentaires"],"r":0,"e":"Elle étudie aussi, dans l'autre sens, l'influence des facteurs génétiques sur la pharmacodynamie, la pharmacocinétique et la toxicologie.","s":2},{"q":"En pharmacologie expérimentale, les essais sont menés :","o":["Chez des volontaires sains","Chez des animaux d'expérience intacts ou sur organes isolés","Chez des patients","En simulation informatique uniquement"],"r":1,"e":"La pharmacologie clinique, chez l'humain, n'est engagée que si la pharmacologie expérimentale s'est révélée sûre.","s":2},{"q":"Lorsqu'il n'existe pas de traitement d'efficacité démontrée pour la maladie étudiée, le groupe contrôle reçoit :","o":["Rien du tout","Un placebo","Une demi-dose","Le traitement à l'étude"],"r":1,"e":"Le groupe contrôle est obligatoire, tout comme la randomisation, qui rend imprévisible l'appartenance de chaque sujet à l'un ou l'autre groupe.","s":2},{"q":"Parmi les essais précliniques, les essais pharmacodynamiques visent à déterminer :","o":["La dose létale","La dose efficace, pour établir l'efficacité","La biodisponibilité","La stabilité chimique"],"r":1,"e":"Les essais toxicologiques déterminent la dose létale ; les essais pharmacocinétiques étudient le devenir du produit dans l'organisme.","s":2},{"q":"En phase I, l'augmentation progressive des doses vise à déterminer :","o":["L'efficacité thérapeutique","La dose maximale sans effets indésirables","La valeur thérapeutique relative","Le rapport risque/bénéfice"],"r":1,"e":"La phase I évalue la toxicité et étudie le métabolisme et la biodisponibilité, chez un nombre restreint de volontaires sains.","s":2},{"q":"La phase II détermine notamment :","o":["La relation dose/réponse et l'intervalle dose/posologie","La dose létale","Les effets indésirables rares","La valeur thérapeutique globale"],"r":0,"e":"Elle stipule la dose thérapeutique humaine et évalue la sécurité à court terme, chez 100 à 200 volontaires malades à pathologie bien caractérisée.","s":2},{"q":"Pourquoi la phase II recrute-t-elle des patients à pathologie bien caractérisée ?","o":["Pour réduire les coûts","Pour éviter les erreurs d'interprétation","Pour accélérer le recrutement","Pour limiter les effets indésirables"],"r":1,"e":"Un échantillon hétérogène rendrait impossible d'attribuer une réponse ou son absence au médicament plutôt qu'à la diversité des tableaux cliniques.","s":2},{"q":"La phase III établit :","o":["La dose maximale tolérée","Le rapport risque/bénéfice ainsi que l'efficacité et la sécurité à court et long terme","La biodisponibilité","La stabilité de la forme galénique"],"r":1,"e":"Elle procède par essai comparatif avec les thérapeutiques alternatives, sur 1 000 à 2 000 patients, avec protocole contrôlé et simple ou double insu.","s":2},{"q":"Un essai en simple insu signifie que :","o":["Ni le patient ni l'investigateur ne savent","Le patient ne sait pas quelle médication il reçoit","L'investigateur ne sait pas","Il n'y a pas de groupe contrôle"],"r":1,"e":"L'essai ouvert : les deux savent. Le double insu : aucun des deux ne sait. L'essai non contrôlé n'a ni groupe contrôle ni rigueur de sélection.","s":2},{"q":"Parmi les trois raisons de l'insu, le cours cite :","o":["Éviter que les professionnels ne modifient le régime ou ne procèdent à un suivi préférentiel","Réduire le coût de l'étude","Accélérer le recrutement","Protéger le secret industriel"],"r":0,"e":"Les deux autres : que le patient ne modifie pas son comportement ni ne surdéclare d'effets indésirables, et éviter les erreurs systématiques d'évaluation par l'investigateur.","s":2},{"q":"Un essai non contrôlé se caractérise par :","o":["L'absence de groupe contrôle et une faible rigueur de sélection diagnostique","L'ignorance du traitement par le patient","Une randomisation stricte","Un double insu"],"r":0,"e":"C'est le degré zéro de la méthodologie : sans comparateur, aucune conclusion causale n'est possible sur l'efficacité observée.","s":2},{"q":"La marge thérapeutique désigne la relation entre :","o":["La dose de charge et la dose d'entretien","La concentration minimale efficace et la concentration maximale tolérée","L'absorption et l'élimination","L'affinité et l'activité intrinsèque"],"r":1,"e":"Plus cette marge est étroite, plus le médicament est délicat à manier : un léger dépassement suffit à passer de l'effet thérapeutique à la toxicité.","s":2},{"q":"La concentration maximale tolérée (CMT) correspond à :","o":["La plus basse concentration produisant l'effet désiré","La plus grande concentration sans effets toxiques","La concentration à l'équilibre","La concentration après une dose de charge"],"r":1,"e":"La CME est la plus basse concentration capable de produire l'effet désiré. L'intervalle entre les deux définit la fenêtre thérapeutique utile.","s":2},{"q":"La dose d'entretien a pour objectif :","o":["D'atteindre rapidement la concentration désirée","De maintenir la concentration à l'équilibre","De saturer les récepteurs","D'accélérer l'élimination"],"r":1,"e":"C'est la dose de charge qui sert à atteindre rapidement la concentration voulue, notamment pour les molécules à demi-vie longue.","s":2},{"q":"L'association aspirine + paracétamol est citée comme exemple :","o":["De synergie additive","De synergie de potentialisation","D'antagonisme compétitif","D'antagonisme chimique"],"r":0,"e":"Dans la synergie additive, A + B égale la somme des effets. Dans la potentialisation, comme captopril + diurétiques, le résultat dépasse cette somme.","s":2},{"q":"Le couple acétylcholine / atropine illustre un antagonisme :","o":["Compétitif, sur les mêmes récepteurs","Physiologique","Chimique","Additif"],"r":0,"e":"L'antagonisme physiologique met en jeu des structures différentes aux effets opposés, comme glucagon et insuline ; l'antagonisme chimique une réaction en solution, comme les chélateurs de métaux lourds.","s":2},{"q":"Les chélateurs de métaux lourds illustrent un antagonisme :","o":["Compétitif","Physiologique","Chimique, par réaction en solution","Fonctionnel"],"r":2,"e":"L'interaction se produit avant toute rencontre avec un récepteur : les deux substances réagissent directement entre elles.","s":2},{"q":"Que signifie l'acronyme ADME ?","o":["Absorption, Distribution, Métabolisation, Excrétion","Action, Dose, Marge, Effet","Affinité, Dynamique, Mécanisme, Élimination","Administration, Diffusion, Métabolisme, Efficacité"],"r":0,"e":"La pharmacocinétique étudie ce que l'organisme fait au médicament : Absorption, Distribution, Métabolisation, Excrétion.","s":3},{"q":"L'absorption d'un médicament est d'autant plus grande que :","o":["La surface de contact est petite","La surface de contact est grande, le temps de contact long, la surface irriguée et la structure fine","La structure est épaisse","Le temps de contact est court"],"r":1,"e":"L'absorption est d'autant plus grande que la surface de contact est grande, le temps de contact long, la surface absorbante irriguée et la structure fine.","s":3},{"q":"Où les acides faibles sont-ils le mieux absorbés ?","o":["Dans la muqueuse gastrique","Dans l'intestin grêle","Dans le côlon","Dans la bouche"],"r":0,"e":"Les acides faibles ont une plus grande absorption dans la muqueuse gastrique, car la proportion de forme non ionisée y est plus grande ; les bases faibles sont mieux absorbées dans l'intestin.","s":3},{"q":"Quelle formule permet d'obtenir le degré d'ionisation d'une substance active ?","o":["La formule de Henderson-Hasselbalch","L'équation de Michaelis-Menten","La loi de Fick","L'équation de Nernst"],"r":0,"e":"Le degré d'ionisation est obtenu par la formule de Henderson-Hasselbalch.","s":3},{"q":"Quelle forme d'une substance active peut traverser les membranes par diffusion simple ?","o":["La forme ionisée, polaire et hydrosoluble","La forme non ionisée","Les deux formes","Aucune des deux"],"r":1,"e":"La forme ionisée est polaire, hydrosoluble et sans capacité de traverser les membranes par diffusion simple : c'est la forme non ionisée qui passe.","s":3},{"q":"Lequel de ces éléments N'EST PAS une voie entérale ?","o":["Voie orale","Voie sublinguale","Voie rectale","Voie sous-cutanée"],"r":3,"e":"Les voies entérales sont l'orale, la sublinguale et la rectale ; la sous-cutanée est parentérale.","s":3},{"q":"Qu'est-ce que l'effet de premier passage hépatique ?","o":["La destruction du médicament par le suc gastrique","La biotransformation du médicament dans le foie après passage par la veine porte, avant d'atteindre la circulation générale","L'élimination rénale immédiate","La liaison aux protéines plasmatiques"],"r":1,"e":"Après administration orale, les vaisseaux de l'intestin et de l'estomac drainent vers la veine porte hépatique puis le foie, où la biotransformation modifie les substances : seulement 50 % ou moins atteindra la veine cave.","s":3},{"q":"Quelle voie évite complètement l'effet de premier passage hépatique ?","o":["La voie orale","La voie sublinguale, qui draine vers la veine cave supérieure","La voie rectale","La voie intramusculaire lente"],"r":1,"e":"La voie sublinguale est sans effet de premier passage car elle draine vers la veine cave supérieure.","s":3},{"q":"Dans quelle proportion la voie rectale évite-t-elle l'effet de premier passage ?","o":["0 %","Partiellement, environ 50 %","100 %","On ne peut pas l'évaluer"],"r":1,"e":"L'effet de premier passage est partiellement évité (50 %) : les veines hémorroïdales supérieures rejoignent la veine porte, les moyennes et inférieures la veine cave inférieure.","s":3},{"q":"Quel médicament est administré par voie sublinguale dans l'angine de poitrine ?","o":["L'insuline","La nitroglycérine","La streptomycine","Le paracétamol"],"r":1,"e":"La nitroglycérine par voie sublinguale est l'exemple donné dans le traitement de l'angine de poitrine.","s":3},{"q":"Quel médicament est détruit par le suc gastrique et ne peut donc pas être pris par voie orale ?","o":["L'insuline","Le paracétamol","L'aspirine","La warfarine"],"r":0,"e":"Certains médicaments sont détruits par le suc gastrique, comme l'insuline ; d'autres ne sont pas absorbés, comme la streptomycine.","s":3},{"q":"Pourquoi l'intestin grêle est-il un meilleur site d'absorption que l'estomac ?","o":["Parce que son pH est plus acide","Parce que sa surface disponible est très grande et le temps de contact long, parfois plusieurs heures","Parce qu'il est moins vascularisé","Parce qu'il ne contient pas d'enzymes"],"r":1,"e":"L'intestin grêle offre une surface disponible très grande et beaucoup de temps de contact, parfois plusieurs heures, contrairement à l'estomac.","s":3},{"q":"À quoi sert principalement la voie intradermique ?","o":["Au dépistage d'allergies et au test tuberculinique","À l'administration d'insuline","Aux grands volumes de perfusion","Aux anesthésiques généraux"],"r":0,"e":"La voie intradermique, administrée sous le derme, sert au dépistage d'allergies et au test tuberculinique ; elle est douloureuse.","s":3},{"q":"Pourquoi la voie sous-cutanée est-elle douloureuse ?","o":["Parce que le tissu est très vascularisé","Parce que le tissu est peu vascularisé mais riche en nerfs","Parce que l'aiguille est longue","Parce que les volumes sont importants"],"r":1,"e":"La voie sous-cutanée est douloureuse car le tissu sous-cutané est peu vascularisé mais riche en nerfs.","s":3},{"q":"Quel est l'effet d'un état de choc sur l'absorption sous-cutanée ?","o":["Elle est accélérée","Elle est réduite par la vasoconstriction","Elle est inchangée","Elle devient immédiate"],"r":1,"e":"L'absorption sous-cutanée est plus réduite chez les patients en état de choc, du fait de la vasoconstriction.","s":3},{"q":"Quel est l'avantage majeur de la voie intraveineuse ?","o":["L'auto-administration possible","Les concentrations sanguines maximales atteintes immédiatement, avec une biodisponibilité de 100 %","L'absorption lente et régulière","L'absence de risque"],"r":1,"e":"La voie IV atteint les concentrations maximales immédiatement après l'injection et offre une biodisponibilité de 100 %, permettant une dose moindre.","s":3},{"q":"Pourquoi la voie intraveineuse est-elle qualifiée de plus dangereuse ?","o":["À cause du plus grand risque de réactions indésirables, notamment anaphylactiques, et du risque d'embolie","À cause de la douleur","À cause de l'absorption irrégulière","À cause du mauvais goût"],"r":0,"e":"C'est la voie la plus dangereuse : plus grand risque de réactions indésirables de type anaphylactique, thrombophlébites, nécrose tissulaire et risque d'embolie.","s":3},{"q":"Quelles solutions sont mieux absorbées par voie intramusculaire ?","o":["Les solutions huileuses","Les solutions aqueuses","Les suspensions","Les émulsions"],"r":1,"e":"Par voie intramusculaire, les solutions aqueuses sont mieux absorbées que les huileuses ou les suspensions.","s":3},{"q":"Quelle voie parentérale est décrite comme aussi rapide que la voie IV ?","o":["La voie intrapéritonéale","La voie intradermique","La voie sous-cutanée","La voie intramusculaire"],"r":0,"e":"L'administration dans la cavité abdominale — voie intrapéritonéale — est présentée comme une voie rapide, comparable à la voie IV.","s":3},{"q":"Quelle est la structure d'un système thérapeutique transdermique ?","o":["Un simple film adhésif imprégné","Un disque multicouche avec un réservoir de médicament entre une membrane imperméable et une membrane microporeuse contrôlant le débit","Une pommade épaisse","Un comprimé à dissoudre sur la peau"],"r":1,"e":"Le système transdermique est un disque multicouche avec un réservoir de médicament entre une membrane imperméable et une membrane microporeuse qui contrôle le débit et la sortie du médicament.","s":3},{"q":"Quelle est la forme topique la plus efficace pour l'absorption cutanée ?","o":["Les poudres","Les lotions","Les pommades, qui conservent l'humidité","Les crèmes de jour"],"r":2,"e":"Les pommades conservent l'humidité, ce qui augmente l'absorption : elles sont le véhicule le plus efficace pour l'absorption de médicaments par la peau.","s":3},{"q":"Quels comprimés ne doivent jamais être mâchés ni écrasés ?","o":["Les comprimés sécables","Les comprimés à enrobage entérique et ceux à libération contrôlée","Les comprimés effervescents","Les comprimés non enrobés"],"r":1,"e":"Les comprimés et gélules avec enrobage, ceux à libération contrôlée (retard) et les comprimés sublinguaux comme la nitroglycérine ne doivent pas être écrasés, mâchés ou dissous.","s":3},{"q":"Quels organes reçoivent la plus forte concentration de médicament du fait de leur irrigation ?","o":["Muscle, peau et tissu adipeux","Cœur, foie, reins et cerveau","Os et cartilage","Tendons et ligaments"],"r":1,"e":"Une plus grande irrigation entraîne une plus grande concentration de médicament : cœur, foie, reins, cerveau ; à l'inverse muscle, peau et tissu adipeux.","s":3},{"q":"Quelle forme du médicament est disponible pour les tissus et le lieu d'action ?","o":["La forme liée aux protéines","La forme libre uniquement","Les deux formes également","Aucune : seule la forme métabolisée agit"],"r":1,"e":"Seule la forme libre du médicament, restée en solution dans le plasma, est disponible pour les tissus et le lieu d'action.","s":3},{"q":"Qu'est-ce qui caractérise la barrière hémato-encéphalique ?","o":["Des cellules endothéliales fenestrées","Des cellules endothéliales non fenestrées unies fermement par des jonctions serrées","Une absence de membrane","Une forte perméabilité aux molécules hydrosolubles"],"r":1,"e":"La barrière hémato-encéphalique est constituée de cellules endothéliales spécialisées, non fenestrées, unies fermement par des jonctions serrées, ce qui empêche le transport des médicaments vers les tissus cérébraux.","s":3},{"q":"Quelle particularité présente la barrière hémato-encéphalique de l'enfant ?","o":["Elle est plus étanche que chez l'adulte","Elle est immature, avec des pores, permettant la diffusion de médicaments qui normalement ne passeraient pas","Elle est absente","Elle ne filtre que les lipides"],"r":1,"e":"Chez l'enfant, la barrière hémato-encéphalique est immature (avec des pores), ce qui permet la diffusion de médicaments qui normalement ne passeraient pas dans le cerveau et la moelle.","s":3},{"q":"Quel est le rôle de la glycoprotéine P placentaire ?","o":["Faciliter le passage des médicaments vers le fœtus","Maintenir le médicament hors de la circulation fœtale : effet protecteur","Métaboliser les médicaments","Acidifier le plasma placentaire"],"r":1,"e":"La glycoprotéine P placentaire maintient le médicament hors de la circulation fœtale, avec un effet protecteur.","s":3},{"q":"Quelles réactions constituent la phase I de la métabolisation ?","o":["Les réactions de conjugaison","L'oxydation par le cytochrome P450, la réduction et l'hydrolyse","L'excrétion biliaire","La liaison aux protéines"],"r":1,"e":"Les réactions de phase I, dites pré-synthétiques, convertissent le médicament en un métabolite plus polaire par oxydation (cytochrome P450), réduction et hydrolyse.","s":3},{"q":"Qu'est-ce qu'un pro-médicament ?","o":["Un médicament à libération prolongée","Une substance inactive ou partiellement active devenant active seulement après métabolisation","Un médicament de première intention","Un médicament générique"],"r":1,"e":"Les pro-médicaments sont des substances inactives ou partiellement actives qui, après administration, sont métabolisées pour générer leur forme active ; exemple : la lévodopa.","s":3},{"q":"À quel pH urinaire les médicaments acides sont-ils ionisés, donc non réabsorbés ?","o":["À pH acide","À pH alcalin","À pH neutre uniquement","Le pH n'a pas d'influence"],"r":1,"e":"Les médicaments acides sont ionisés à pH urinaire alcalin ; les médicaments basiques sont ionisés à pH urinaire acide. D'où l'alcalinisation de l'urine pour éliminer les barbituriques.","s":3},{"q":"Parmi les facteurs d'absorption liés au MÉDICAMENT, le cours cite :","o":["La vascularisation du site","La forme pharmaceutique, la liposolubilité, le poids moléculaire et le degré d'ionisation","Le pH de l'estomac","La vitesse de vidange gastrique"],"r":1,"e":"Les facteurs liés à l'organisme sont la vascularisation du site, la surface de contact, les pathologies, la vidange gastrique et le pH digestif.","s":3},{"q":"La forme ionisée d'une substance active est :","o":["Liposoluble et diffusible","Polaire, hydrosoluble et incapable de traverser les membranes par diffusion simple","Toujours inactive","Plus rapidement métabolisée"],"r":1,"e":"C'est pourquoi le pH du milieu détermine largement le site d'absorption : il fixe la proportion de forme non ionisée disponible.","s":3},{"q":"Parmi les inconvénients de la voie orale, le cours cite :","o":["Une absorption trop rapide","Une absorption lente et irrégulière, inadaptée aux urgences","Un coût élevé","L'impossibilité de doses exactes"],"r":1,"e":"S'y ajoutent nausées et vomissements, mauvais goût, non-absorption de certains produits comme la streptomycine, destruction gastrique de l'insuline et effet de premier passage.","s":3},{"q":"L'estomac est un site d'absorption médiocre parce qu'il présente :","o":["Une surface relativement petite, peu de temps de contact et un contact muqueux pas toujours intime","Un pH trop élevé","Une vascularisation nulle","Une absence d'enzymes"],"r":0,"e":"L'intestin grêle offre à l'inverse une très grande surface et un temps de contact long, parfois de plusieurs heures.","s":3},{"q":"Par voie rectale, les veines hémorroïdales moyennes et inférieures permettent :","o":["Une absorption retardée par liaison à la veine porte","Une absorption immédiate par liaison directe à la veine cave inférieure","Une absorption nulle","Un passage hépatique complet"],"r":1,"e":"Les veines hémorroïdales supérieures rejoignent au contraire la veine porte, d'où un effet de premier passage seulement partiellement évité — environ 50 %.","s":3},{"q":"Parmi les inconvénients de la voie rectale, le cours mentionne :","o":["Une absorption lente en présence de selles","Un effet de premier passage total","L'impossibilité d'usage chez l'enfant","Un risque d'anaphylaxie"],"r":0,"e":"S'y ajoutent l'inconfort, l'irritation de la muqueuse avec possible saignement rectal, et le caractère psychologiquement désagréable.","s":3},{"q":"La voie sublinguale évite l'effet de premier passage parce que le sang veineux rejoint :","o":["La veine porte","La veine cave supérieure","L'artère hépatique","Le canal thoracique"],"r":1,"e":"Tous les médicaments ne s'y prêtent pas : il faut des molécules petites ou à coefficient de partage huile/eau élevé. Elle est en outre mal tolérée au goût.","s":3},{"q":"La voie intradermique est principalement utilisée pour :","o":["Les traitements au long cours","Le dépistage d'allergies et le test tuberculinique","Les urgences","L'insulinothérapie"],"r":1,"e":"Elle est douloureuse et ne permet que de très faibles volumes, ce qui la réserve aux usages diagnostiques.","s":3},{"q":"La voie sous-cutanée présente comme avantage :","o":["La possibilité d'auto-injection et d'implants","Des volumes importants","Une absorption immédiate","L'administration de solutions huileuses"],"r":0,"e":"Ses inconvénients : absorption lente, réduite en état de choc par vasoconstriction, volumes réduits, douleur, et impossibilité des solutions huileuses.","s":3},{"q":"Par voie intramusculaire, l'absorption est plus uniforme :","o":["Dans un petit muscle","Dans un grand muscle","En position debout","Chez le sujet déshydraté"],"r":1,"e":"Cette voie convient aux médicaments non irritants ; les solutions aqueuses y sont mieux absorbées que les huileuses ou les suspensions.","s":3},{"q":"Parmi les inconvénients de la voie intramusculaire figure :","o":["L'impossibilité d'auto-administration et le risque d'hématomes","Une biodisponibilité nulle","Un effet de premier passage majeur","L'absence d'effet local"],"r":0,"e":"S'y ajoutent l'irritation locale fréquente, la douleur ou l'abcès au point d'injection, et la limitation des volumes.","s":3},{"q":"La voie intraveineuse offre une biodisponibilité de :","o":["50 %","80 %","100 %","Variable selon le site"],"r":2,"e":"Les concentrations sanguines sont maximales immédiatement après l'injection et de grands volumes sont possibles — au prix d'une dangerosité accrue.","s":3},{"q":"Les dangers propres à la voie intraveineuse cités par le cours sont :","o":["Les réactions anaphylactiques, les thrombophlébites et l'embolie","L'irritation musculaire","La destruction gastrique","L'absorption erratique"],"r":0,"e":"L'absence de toute étape d'absorption supprime le filtre naturel qui, par les autres voies, ralentit et atténue l'arrivée du produit.","s":3},{"q":"Les organes recevant la plus forte concentration de médicament du fait de leur irrigation sont :","o":["Le muscle, la peau et le tissu adipeux","Le cœur, le foie, les reins et le cerveau","Les os et les cartilages","Les poumons uniquement"],"r":1,"e":"Muscle, peau et tissu adipeux, moins irrigués, reçoivent le médicament plus lentement — mais peuvent constituer des réservoirs de relargage.","s":3},{"q":"Seule est disponible pour les tissus et le lieu d'action :","o":["La forme liée aux protéines plasmatiques","La forme libre","La forme métabolisée","La forme ionisée"],"r":1,"e":"La fraction liée à l'albumine constitue une réserve circulante inactive ; tout ce qui déplace cette liaison augmente brutalement la fraction active.","s":3},{"q":"La barrière hémato-encéphalique se caractérise par :","o":["Des capillaires fenestrés","Des cellules endothéliales non fenestrées unies par des jonctions serrées","Une absence d'endothélium","Des pores larges chez l'adulte"],"r":1,"e":"Elle est immature chez l'enfant, où elle présente des pores — ce qui explique une sensibilité accrue à certaines substances.","s":3},{"q":"Le plasma placentaire, comparé à celui de la mère, est :","o":["Plus alcalin","Plus acide","De pH identique","Dépourvu de protéines"],"r":1,"e":"Cette différence de pH modifie l'ionisation des substances et peut entraîner un piégeage de certains médicaments du côté fœtal.","s":3},{"q":"La métabolisation transforme les médicaments en substances :","o":["Plus liposolubles","Moins liposolubles et plus facilement excrétables","Toujours inactives","Plus volumineuses"],"r":1,"e":"Son siège principal est le réticulum endoplasmique lisse du foie. C'est la condition de l'élimination rénale, qui exige des composés hydrosolubles.","s":3},{"q":"La phase I de la métabolisation produit un métabolite :","o":["Toujours inactif","Plus polaire, pouvant être inactif, moins actif ou plus actif","Toujours plus actif","Identique au produit initial"],"r":1,"e":"La transformation de la codéine en morphine illustre le cas où le métabolite est plus actif que la molécule mère.","s":3},{"q":"L'oxydation de phase I fait principalement intervenir :","o":["Le cytochrome P450","La glucuronyl-transférase","L'anhydrase carbonique","La monoamine oxydase uniquement"],"r":0,"e":"Les réactions de phase I sont l'oxydation, la réduction et l'hydrolyse. La phase II conjugue avec glucuronate, sulfate ou acétate.","s":3},{"q":"Quel anesthésique local NE provoque PAS de vasodilatation ?","o":["La lidocaïne","La cocaïne","La bupivacaïne","La procaïne"],"r":1,"e":"Tous les anesthésiques locaux provoquent une vasodilatation à l'exception de la cocaïne ; c'est pourquoi on les associe à l'adrénaline pour obtenir un effet local.","s":4},{"q":"Pourquoi associe-t-on l'adrénaline aux anesthésiques locaux ?","o":["Pour accélérer la diffusion systémique","Pour obtenir une vasoconstriction et donc un effet local","Pour prolonger la métabolisation hépatique","Pour réduire la douleur de l'injection"],"r":1,"e":"Comme les anesthésiques locaux provoquent une vasodilatation, on les administre avec adrénaline (vasoconstriction) pour obtenir un effet local ; exemple : lidocaïne + adrénaline chez le dentiste.","s":4},{"q":"Quel est le mécanisme d'action des anesthésiques locaux ?","o":["Le blocage de la conduction nerveuse au site d'administration","L'inhibition des cyclooxygénases","L'agonisme GABA","Le blocage des canaux calciques cardiaques"],"r":0,"e":"Les anesthésiques locaux agissent par blocage de la conduction nerveuse au site d'administration.","s":4},{"q":"Quelles sont les trois classes de relaxants musculaires ?","o":["Action centrale, action directe sur le muscle et action périphérique","Action rapide, intermédiaire et lente","Orale, intrathécale et intramusculaire","Dépolarisants, non dépolarisants et mixtes"],"r":0,"e":"Les relaxants musculaires peuvent être à action centrale, à action directe sur le muscle ou à action périphérique.","s":4},{"q":"Quel est le mécanisme du baclofène ?","o":["Agoniste des récepteurs alpha-2 adrénergiques","Agoniste des récepteurs GABA-B, déprimant la transmission nerveuse au niveau de la moelle épinière","Blocage de la libération du calcium sarcoplasmique","Blocage compétitif de la jonction neuromusculaire"],"r":1,"e":"Le baclofène est un agoniste des récepteurs GABA-B ; il déprime la transmission nerveuse médullaire par inhibition de l'action du glutamate et de l'aspartate.","s":4},{"q":"Pourquoi la voie intrathécale est-elle plus efficace que la voie orale pour le baclofène ?","o":["Parce que le baclofène est détruit dans l'estomac","Parce que le baclofène ne traverse pas facilement la barrière hémato-encéphalique","Parce que la dose orale est insuffisante","Parce que la voie orale est douloureuse"],"r":1,"e":"Le baclofène ne traverse pas facilement la barrière hémato-encéphalique : son administration orale est moins efficace que la voie intrathécale.","s":4},{"q":"Quelles sont les indications cliniques du baclofène ?","o":["La spasticité musculaire dans la sclérose en plaques et les lésions de la moelle épinière","L'hyperthermie maligne","Le blépharospasme","Les arythmies cardiaques"],"r":0,"e":"Le baclofène est indiqué dans la spasticité musculaire de la sclérose en plaques et les lésions de la moelle épinière.","s":4},{"q":"Qu'est-ce que la voie intrathécale ?","o":["Une injection intramusculaire profonde","Une injection dans le canal rachidien, directement dans l'espace sous-arachnoïdien, évitant la barrière hémato-encéphalique","Une perfusion veineuse centrale","Une administration par patch transdermique"],"r":1,"e":"La voie intrathécale consiste à injecter des substances dans le canal rachidien, directement dans l'espace sous-arachnoïdien, évitant ainsi la barrière hémato-encéphalique ; elle est très douloureuse et à n'utiliser que si nécessaire.","s":4},{"q":"Quel est le mécanisme de la tizanidine ?","o":["Agoniste GABA-B","Agoniste des récepteurs alpha-2 adrénergiques, inhibant la libération d'acides aminés excitateurs stimulant les récepteurs NMDA","Antagoniste de la dopamine","Blocage des canaux sodiques"],"r":1,"e":"La tizanidine est un agoniste des récepteurs alpha-2 adrénergiques qui inhibe la libération d'acides aminés excitateurs stimulant les récepteurs NMDA, agissant surtout au niveau de la moelle épinière.","s":4},{"q":"Quelle est la contre-indication majeure de la tizanidine ?","o":["L'insuffisance rénale","Les troubles hépatiques et l'insuffisance hépatique grave","L'asthme","Le diabète"],"r":1,"e":"Les contre-indications de la tizanidine sont les troubles hépatiques et l'insuffisance hépatique grave.","s":4},{"q":"Quelle est la contre-indication du thiocolchicoside ?","o":["La myasthénie grave","L'hypertension artérielle","L'insuffisance rénale","La grossesse uniquement"],"r":0,"e":"Le thiocolchicoside est contre-indiqué dans la myasthénie grave ; sa dose maximale journalière est de 32 mg.","s":4},{"q":"Quel est le mécanisme du dantrolène ?","o":["Agoniste GABA-A","Il bloque la libération des ions calcium du réticulum sarcoplasmique et inhibe donc la contraction musculaire","Il bloque la libération d'acétylcholine","Il inhibe les cyclooxygénases"],"r":1,"e":"Le dantrolène agit directement sur le muscle squelettique : il bloque la libération des ions calcium du réticulum sarcoplasmique, interférant avec la disponibilité du calcium intracellulaire fondamental pour la contraction.","s":4},{"q":"Quelles sont les indications du dantrolène ?","o":["La spasticité de la sclérose en plaques","Le traitement des hyperthermies malignes et du syndrome malin des neuroleptiques","Le torticolis","Le tétanos"],"r":1,"e":"Le dantrolène est utilisé dans le traitement des hyperthermies malignes et du syndrome malin des neuroleptiques, en milieu hospitalier.","s":4},{"q":"Quel curarisant est un bloqueur DÉPOLARISANT ?","o":["La tubocurarine","Le pancuronium","Le chlorure de suxaméthonium (succinylcholine)","L'atracurium"],"r":2,"e":"Le chlorure de suxaméthonium (succinylcholine) agit en provoquant une dépolarisation de la plaque motrice ; les autres cités sont non dépolarisants (compétitifs).","s":4},{"q":"Quelle est la durée d'action du suxaméthonium ?","o":["5 à 10 minutes","10 à 15 minutes","30 à 45 minutes","Plus de 2 heures"],"r":0,"e":"La durée d'action du suxaméthonium est de 5 à 10 minutes ; ses effets indésirables incluent l'augmentation de la pression intra-oculaire, l'arythmie et l'arrêt cardiaque.","s":4},{"q":"Pourquoi la durée d'action de l'atracurium est-elle peu dépendante de l'élimination rénale ?","o":["Parce qu'il est éliminé par la bile","Parce qu'il subit une dégradation spontanée, par voie enzymatique, très rapide","Parce qu'il n'est pas métabolisé","Parce qu'il est administré par voie inhalatoire"],"r":1,"e":"L'atracurium subit une dégradation spontanée par voie enzymatique très rapide, d'où une durée d'action de 10 à 15 minutes peu dépendante de l'élimination rénale.","s":4},{"q":"Quel curarisant provoque la plus forte libération d'histamine ?","o":["La tubocurarine","Le pancuronium","Le vécuronium","L'atracurium"],"r":0,"e":"La tubocurarine est parmi ceux de plus longue durée et provoque une libération d'histamine avec bronchospasme, hypotension, hypersécrétion salivaire et bronchique.","s":4},{"q":"Quel antagoniste distingue le récepteur nicotinique NM du muscle squelettique ?","o":["L'hexaméthonium","La tubocurarine","L'atropine","Le flumazénil"],"r":1,"e":"Les sous-types nicotiniques se différencient par leur antagoniste : la tubocurarine pour le NM du muscle squelettique, l'hexaméthonium pour le NT neuronal.","s":4},{"q":"Quel est le mécanisme de la toxine botulique de type A ?","o":["Elle bloque les récepteurs nicotiniques","Elle se lie aux membranes pré-synaptiques des neurones moteurs et bloque la libération d'acétylcholine","Elle bloque le calcium sarcoplasmique","Elle agit sur les récepteurs GABA"],"r":1,"e":"La toxine botulique se lie aux membranes pré-synaptiques des neurones moteurs à la jonction neuromusculaire, bloquant la libération d'acétylcholine et empêchant la contraction : il en résulte une paralysie.","s":4},{"q":"Laquelle de ces indications est citée pour la toxine botulique ?","o":["La motricité de la main dans les hémiplégies spastiques","L'hyperthermie maligne","L'anxiété généralisée","L'ulcère gastrique"],"r":0,"e":"Le champ d'application couvre les situations avec dystonie musculaire : torticolis, hémispasme facial, blépharospasme, motricité de la main dans les hémiplégies spastiques, achalasie de l'œsophage.","s":4},{"q":"Quel est le mécanisme des benzodiazépines ?","o":["Antagonistes de la dopamine","Agonistes allostériques des récepteurs GABA, ouvrant les canaux chlore et provoquant une hyperpolarisation","Inhibiteurs de la recapture de la sérotonine","Bloqueurs des canaux calciques"],"r":1,"e":"Les benzodiazépines sont des agonistes allostériques des récepteurs GABA : l'ouverture des canaux chlore entraîne une hyperpolarisation qui réduit l'excitabilité neuronale.","s":4},{"q":"Quel est l'antidote des benzodiazépines ?","o":["La N-acétylcystéine","Le flumazénil","La naloxone","L'atropine"],"r":1,"e":"Le flumazénil est un antagoniste compétitif à forte affinité pour les récepteurs BZ ; sa demi-vie courte (0,7-1,3 h) impose de surveiller la demi-vie plus longue des benzodiazépines.","s":4},{"q":"Quelle interaction alimentaire augmente la toxicité du diazépam ?","o":["Le jus de pamplemousse, inhibiteur du CYP 3A4","Le lait","Le café","Les produits riches en protéines"],"r":0,"e":"Le jus de pamplemousse a un effet inhibiteur sur le CYP 3A4, augmentant la concentration plasmatique du diazépam et donc la dépression du SNC : il faut éviter l'administration conjointe.","s":4},{"q":"Comment les AINS agissent-ils sur la douleur ?","o":["En bloquant la conduction du signal nerveux","En diminuant la synthèse des prostaglandines au site d'agression, avant la génération du signal de douleur","En agissant sur les récepteurs opioïdes","En bloquant les canaux sodiques"],"r":1,"e":"Les AINS diminuent la synthèse des prostaglandines au site d'agression : ils agissent avant la génération du signal de douleur et n'interfèrent pas avec sa conduction.","s":4},{"q":"Quel AINS est considéré comme le plus sûr ?","o":["Le piroxicam","L'ibuprofène","Le diclofénac","L'indométacine"],"r":1,"e":"L'ibuprofène est mieux toléré, avec des effets secondaires plus légers et de moindre incidence : il est considéré comme l'AINS le plus sûr.","s":4},{"q":"Quelle est la particularité du piroxicam ?","o":["Une demi-vie très courte de 4 h","Une demi-vie plasmatique assez longue, jusqu'à 48 h, avec plus d'hémorragies chez la personne âgée","Une absence de toxicité digestive","Une action exclusivement locale"],"r":1,"e":"Le piroxicam est lentement éliminé, avec une demi-vie plasmatique pouvant atteindre 48 h, et une incidence plus élevée d'hémorragies chez les personnes âgées à doses élevées.","s":4},{"q":"Quel est le risque majeur des inhibiteurs sélectifs de la COX-2 ?","o":["Une toxicité gastrique accrue","Un risque augmenté de maladies cardiovasculaires","Une néphrotoxicité systématique","Une ototoxicité"],"r":1,"e":"Les coxibs ont moins d'effets gastro-intestinaux car ils n'inhibent pas la COX-1, protectrice du tube digestif, mais présentent un risque augmenté de maladies cardiovasculaires.","s":4},{"q":"Quel métabolite est responsable de la toxicité hépatique du paracétamol ?","o":["Le métabolite glucuronide","Le métabolite sulfate","La N-acétyl-para-benzoquinone imine (NAPQI)","L'acide mercapturique"],"r":2,"e":"L'oxydation par le cytochrome P450 (5-10 %) engendre la NAPQI, métabolite réactif ; normalement conjuguée au glutathion, elle devient toxique quand le glutathion descend sous 30 % des valeurs normales.","s":4},{"q":"Quel est l'antidote de l'intoxication au paracétamol ?","o":["Le flumazénil","La N-acétylcystéine, source de glutathion","L'atropine","La vitamine K"],"r":1,"e":"On administre de la N-acétylcystéine, source de glutathion, pour protéger l'hépatocyte de la lésion par le NAPQI.","s":4},{"q":"Quels sont les signes du salicylisme ?","o":["Nausées, vomissements, acouphènes, céphalées, troubles visuels et surdité","Bradycardie et hypothermie","Éruption cutanée isolée","Polyurie et polydipsie"],"r":0,"e":"Le salicylisme associe nausées, vomissements, acouphènes, céphalées, troubles visuels et surdité ; il n'existe pas d'antidote, on alcalinise l'urine et on recourt à l'hémodialyse.","s":4},{"q":"Combien de grands groupes thérapeutiques la classification du cours distingue-t-elle ?","o":["10","15","20","25"],"r":2,"e":"Les dix premiers vont des anti-infectieux à la médication antiallergique ; les suivants couvrent nutrition, dermatologie, ORL, ophtalmologie, antinéoplasiques, intoxications, vaccins, diagnostic et matériel.","s":4},{"q":"L'association amoxicilline + acide clavulanique appartient aux :","o":["Antibactériens","Antifongiques","Antiviraux","Antiparasitaires"],"r":0,"e":"Le fluconazole et la nystatine sont antifongiques, l'aciclovir antiviral, l'albendazole et la quinine antiparasitaires.","s":4},{"q":"La règle d'usage des anti-infectieux énoncée par le cours est d'utiliser :","o":["L'antimicrobien le plus large possible","L'antimicrobien le plus efficace et de moindre spectre d'activité en premier choix","Systématiquement une association","Le moins coûteux"],"r":1,"e":"Un spectre étroit limite la pression de sélection sur les bactéries non visées. Le cours met aussi en garde contre les doses subthérapeutiques.","s":4},{"q":"Les effets indésirables les plus fréquents des anti-infectieux sont :","o":["Les réactions allergiques et les éruptions cutanées","La néphrotoxicité","L'ototoxicité","Les troubles cardiaques"],"r":0,"e":"La néphrotoxicité et l'ototoxicité caractérisent plus spécifiquement les aminosides, comme la gentamicine.","s":4},{"q":"Dans le système nerveux autonome, les fibres afférentes :","o":["Naissent dans le système nerveux central","Prennent origine dans les viscères et les vaisseaux et conditionnent les réflexes végétatifs","Sont interrompues par une synapse ganglionnaire","Innervent le muscle squelettique"],"r":1,"e":"Les fibres efférentes, motrices, naissent dans le système nerveux et comportent un neurone pré-ganglionnaire et un neurone post-ganglionnaire.","s":4},{"q":"Les anesthésiques locaux agissent en :","o":["Bloquant la conduction nerveuse au site d'administration","Inhibant les cyclooxygénases","Activant les récepteurs GABA","Bloquant la libération de calcium"],"r":0,"e":"Leur danger principal tient à l'atteinte d'organes vitaux en cas de passage systémique — le cours cite la lidocaïne et le système cardiovasculaire.","s":4},{"q":"Le baclofène est un agoniste :","o":["GABA-A","GABA-B","Alpha-2 adrénergique","NMDA"],"r":1,"e":"Il déprime la transmission nerveuse médullaire en inhibant le glutamate et l'aspartate. Le thiocolchicoside agit sur GABA-A et GABA-B, la tizanidine sur les récepteurs alpha-2.","s":4},{"q":"La voie intrathécale est préférée pour le baclofène parce que celui-ci :","o":["Est détruit par le suc gastrique","Ne traverse pas facilement la barrière hémato-encéphalique","Est trop coûteux par voie orale","Provoque des nausées"],"r":1,"e":"L'administration directe dans l'espace sous-arachnoïdien contourne l'obstacle et permet des doses très inférieures pour un effet médullaire supérieur.","s":4},{"q":"La tizanidine inhibe la libération d'acides aminés excitateurs agissant sur les récepteurs :","o":["GABA-A","NMDA","Nicotiniques","Muscariniques"],"r":1,"e":"Elle agit surtout au niveau médullaire, s'administre par voie orale, et sa contre-indication majeure est l'insuffisance hépatique grave.","s":4},{"q":"Le thiocolchicoside est contre-indiqué :","o":["Dans l'insuffisance hépatique grave","Dans la myasthénie grave","Dans l'asthme","Dans l'insuffisance rénale"],"r":1,"e":"Sa dose maximale est de 32 mg par jour et le cours juge son utilité clinique douteuse. L'insuffisance hépatique grave contre-indique la tizanidine.","s":4},{"q":"Le dantrolène agit en :","o":["Bloquant la libération du calcium du réticulum sarcoplasmique","Activant les récepteurs GABA-B","Bloquant les récepteurs nicotiniques","Inhibant l'acétylcholinestérase"],"r":0,"e":"Il inhibe ainsi directement la contraction, au niveau du muscle lui-même. Ses indications sont l'hyperthermie maligne et le syndrome malin des neuroleptiques, en usage hospitalier.","s":4},{"q":"Parmi les curarisants non dépolarisants, le cours cite :","o":["Le suxaméthonium","La tubocurarine, le vécuronium, le pancuronium et l'atracurium","La toxine botulique","Le dantrolène"],"r":1,"e":"Ce sont des bloqueurs compétitifs. Le suxaméthonium est le seul dépolarisant cité, avec une durée d'action de 5 à 10 minutes.","s":4},{"q":"Les risques propres au suxaméthonium cités par le cours sont :","o":["Une augmentation de la pression intraoculaire, des arythmies et un arrêt cardiaque","Une libération massive d'histamine","Une apnée par accumulation hépatique","Une hyperthermie isolée"],"r":0,"e":"Les critères de choix d'un curarisant sont la durée d'action et les effets indésirables : apnée prolongée, collapsus, libération d'histamine.","s":4},{"q":"La toxine botulique de type A agit en :","o":["Bloquant les récepteurs nicotiniques","Se liant aux membranes pré-synaptiques des neurones moteurs et en bloquant la libération d'acétylcholine","Détruisant la plaque motrice","Inhibant la libération de calcium"],"r":1,"e":"Il en résulte une paralysie. Ses indications incluent torticolis, hémispasme facial, blépharospasme, motricité de la main dans les hémiplégies spastiques et achalasie.","s":4},{"q":"Les benzodiazépines agissent comme :","o":["Agonistes directs du récepteur GABA-A","Agonistes allostériques du récepteur GABA-A, favorisant l'ouverture des canaux chlore","Antagonistes du GABA","Inhibiteurs des phosphodiestérases"],"r":1,"e":"L'entrée de chlore hyperpolarise la membrane et réduit l'excitabilité. Elles sont anxiolytiques, hypnotiques, anticonvulsivantes, relaxantes musculaires et amnésiantes.","s":4},{"q":"L'antidote des benzodiazépines est :","o":["La N-acétylcystéine","Le flumazénil","La naloxone","L'atropine"],"r":1,"e":"La N-acétylcystéine est l'antidote du paracétamol. Le salicylisme, lui, n'a pas d'antidote : on alcalinise l'urine et on recourt à l'hémodialyse.","s":4},{"q":"Les AINS agissent sur la douleur :","o":["En bloquant sa conduction nerveuse","Avant la génération du signal douloureux, en réduisant la synthèse des prostaglandines au site d'agression","Au niveau central uniquement","En bloquant les récepteurs opioïdes"],"r":1,"e":"Ils inhibent les cyclooxygénases COX-1 et COX-2. Cette action périphérique explique qu'ils n'interfèrent pas avec la conduction du message nociceptif.","s":4},{"q":"L'AINS considéré comme le plus sûr est :","o":["Le diclofénac","L'ibuprofène","Le piroxicam","Le célécoxib"],"r":1,"e":"Le diclofénac a une demi-vie de 4 heures et une liaison protéique de 99 % ; le piroxicam une demi-vie pouvant atteindre 48 heures et davantage d'hémorragies chez la personne âgée.","s":4},{"q":"Les inhibiteurs sélectifs de la COX-2 se caractérisent par :","o":["Une toxicité gastrique majorée","Une moindre toxicité gastrique mais un risque cardiovasculaire augmenté","Une absence d'effet anti-inflammatoire","Une élimination exclusivement rénale"],"r":1,"e":"Épargner la COX-1 protège la muqueuse gastrique, mais déséquilibre la balance entre prostacycline et thromboxane au profit de la thrombose.","s":4},{"q":"Le mécanisme analgésique du paracétamol passe par le métabolite :","o":["NAPQI","AM404, agissant sur TRPV1 et les récepteurs cannabinoïdes 1","L'acide salicylique","Le glutathion"],"r":1,"e":"Le NAPQI est au contraire le métabolite toxique, responsable de l'atteinte hépatique quand les réserves de glutathion descendent sous 30 %.","s":4},{"q":"Quel est le mécanisme des IEC comme le captopril ?","o":["Ils bloquent les récepteurs bêta-1","Ils inhibent la conversion de l'angiotensine I en angiotensine II","Ils inhibent la réabsorption du sodium","Ils bloquent les canaux calciques"],"r":1,"e":"Les IEC inhibent la conversion de l'angiotensine I en II ; l'angiotensine II est un puissant vasoconstricteur qui stimule la production d'aldostérone, favorisant la rétention de sodium et d'eau.","s":5},{"q":"Quel est le principal problème des IEC comme l'énalapril ?","o":["L'hypertension paradoxale","L'hypotension, nécessitant un ajustement graduel de la dose","La bronchoconstriction","L'hypoglycémie"],"r":1,"e":"L'hypotension est le problème signalé avec l'énalapril et le captopril, ce qui impose un ajustement graduel de la dose.","s":5},{"q":"Quel est le mécanisme du furosémide ?","o":["Il inhibe la réabsorption du sodium, réduisant la rétention d'eau","Il bloque l'enzyme de conversion","Il bloque les récepteurs alpha-1","Il inhibe l'anhydrase carbonique"],"r":0,"e":"Le furosémide, diurétique de l'anse, inhibe la réabsorption du sodium, ce qui réduit la rétention d'eau.","s":5},{"q":"Que provoque le blocage des récepteurs β1 ?","o":["Une bronchoconstriction","Une diminution de la force contractile et du travail cardiaque","Une mydriase","Une vasodilatation périphérique"],"r":1,"e":"Le blocage des récepteurs β1 provoque une diminution de la force contractile et du travail cardiaque.","s":5},{"q":"Pourquoi un bêtabloquant non sélectif peut-il déclencher une crise d'asthme ?","o":["Parce qu'il bloque les récepteurs β2, responsables de la bronchodilatation","Parce qu'il augmente les sécrétions bronchiques","Parce qu'il bloque les récepteurs alpha","Parce qu'il provoque une vasodilatation pulmonaire"],"r":0,"e":"Les récepteurs β2 assurent la bronchodilatation ; un bloqueur β non sélectif les bloque aussi, conduisant à la bronchoconstriction et donc à des crises d'asthme.","s":5},{"q":"Quels sont les trois mécanismes antihypertenseurs prédominants des bêtabloquants ?","o":["Baisse du débit cardiaque, inhibition de la sécrétion rénale dépendante des catécholamines, baisse des résistances vasculaires périphériques","Vasodilatation, diurèse et bradycardie","Blocage calcique, inhibition de la rénine et diurèse","Baisse du volume plasmatique uniquement"],"r":0,"e":"Les mécanismes prédominants sont la baisse du débit cardiaque, l'inhibition de la sécrétion rénale dépendante des catécholamines et la baisse des résistances vasculaires périphériques.","s":5},{"q":"Quelle place thérapeutique occupent les bêtabloquants dans l'HTA ?","o":["Traitement de dernier recours","Antihypertenseurs de 1re ligne, d'usage chronique","Uniquement en urgence hypertensive","Ils ne sont plus utilisés"],"r":1,"e":"Les bêtabloquants sont considérés comme antihypertenseurs de 1re ligne, d'usage chronique ; ils préviennent aussi la tachycardie réflexe déclenchée par les vasodilatateurs directs.","s":5},{"q":"À partir de quelles valeurs parle-t-on d'hypertension artérielle ?","o":["Supérieures à 120 et/ou 80 mmHg","Supérieures à 130 et/ou 85 mmHg","Supérieures à 140 et/ou 90 mmHg","Supérieures à 160 et/ou 100 mmHg"],"r":2,"e":"On parle d'HTA lorsque les valeurs de tension sont supérieures à 140 et/ou 90 mmHg (systolique et diastolique).","s":5},{"q":"Quelles mesures de mode de vie le cours cite-t-il pour contrôler la tension artérielle ?","o":["Réduction du poids, faible consommation de NaCl, limitation de l'alcool et exercice physique régulier","Repos strict et régime hyperprotéiné","Augmentation des apports en sodium","Jeûne intermittent"],"r":0,"e":"Le contrôle de la tension repose d'abord sur des modes de vie sains : réduction du poids, faible consommation de NaCl, limitation de l'alcool, exercice physique régulier.","s":5},{"q":"Comment agissent les médicaments du traitement symptomatique de l'angine de poitrine ?","o":["Uniquement en dilatant les coronaires","Soit en réduisant le besoin en oxygène du myocarde, soit en augmentant le débit sanguin dans les zones ischémiées","En augmentant la force contractile","En accélérant la fréquence cardiaque"],"r":1,"e":"Les médicaments de l'angine agissent soit par réduction du besoin en oxygène du myocarde (bêtabloquants), soit par augmentation du débit sanguin dans les zones ischémiées (nitrates, bloqueurs calciques, allongement de la diastole).","s":5},{"q":"À quelle classe chimique appartiennent majoritairement les vénotropes ?","o":["Aux flavonoïdes ou substances apparentées","Aux xanthines","Aux salicylés","Aux stéroïdes"],"r":0,"e":"Les vénotropes sont majoritairement, chimiquement, des flavonoïdes ou des substances apparentées ; la diosmine diminue la perméabilité capillaire.","s":5},{"q":"Quel est le mécanisme des statines ?","o":["Inhibition de l'absorption intestinale du cholestérol","Inhibition de l'HMG-CoA réductase, enzyme limitante de la production hépatique de cholestérol","Blocage des récepteurs LDL","Stimulation de l'excrétion biliaire"],"r":1,"e":"Les statines inhibent l'hydroxy-3-méthyl-glutaryl-CoA réductase, enzyme limitante de la production de cholestérol dans le foie, sur la voie du mévalonate.","s":5},{"q":"Quels sont les trois effets lipidiques des statines ?","o":["Baisse du LDL, augmentation du HDL et diminution des triglycérides","Augmentation du LDL et du HDL","Baisse du HDL et des triglycérides","Aucun effet sur les triglycérides"],"r":0,"e":"Les statines abaissent le LDL, augmentent le HDL et diminuent les triglycérides.","s":5},{"q":"Quel effet indésirable musculaire caractérise les statines ?","o":["Une atrophie musculaire progressive","Des crampes, une asthénie et une élévation de la créatine kinase","Une hypertrophie musculaire","Une paralysie flasque"],"r":1,"e":"Les statines peuvent provoquer asthénie, crampes, augmentation des transaminases et élévation de l'enzyme créatine kinase.","s":5},{"q":"Quelle est la cible de cholestérol LDL pour les groupes à risque ?","o":["< 190 mg/dl","< 150 mg/dl","< 115 mg/dl","< 100 mg/dl"],"r":3,"e":"Le cholestérol LDL doit être inférieur à 115 mg/dl, et inférieur à 100 mg/dl pour les groupes à risque.","s":5},{"q":"Quel est le rôle de l'ézétimibe en association avec une statine ?","o":["Il réduit l'absorption du cholestérol dans l'intestin","Il inhibe aussi l'HMG-CoA réductase","Il augmente l'excrétion urinaire du cholestérol","Il protège le foie"],"r":0,"e":"L'ézétimibe, administré en association avec une statine, réduit l'absorption du cholestérol dans l'intestin.","s":5},{"q":"Quel est le mécanisme de la warfarine ?","o":["Elle active l'antithrombine","Antagoniste de la vitamine K : elle bloque la carboxylation du glutamate des précurseurs des facteurs de coagulation","Elle inhibe l'agrégation plaquettaire","Elle dissout la fibrine"],"r":1,"e":"La warfarine est un antagoniste de la vitamine K : elle bloque la carboxylation du glutamate des précurseurs des facteurs de coagulation, dépendante de la vitamine K.","s":5},{"q":"Quel paramètre surveille-t-on sous warfarine ?","o":["L'INR","La créatine kinase","La glycémie","La kaliémie"],"r":0,"e":"Le risque hémorragique de la warfarine est surveillé par l'INR.","s":5},{"q":"Pourquoi la warfarine est-elle contre-indiquée au premier trimestre de grossesse ?","o":["Parce qu'elle est tératogène","Parce qu'elle provoque des nausées","Parce qu'elle est inefficace","Parce qu'elle est mal absorbée"],"r":0,"e":"La warfarine est contre-indiquée au premier trimestre car elle est tératogène, et dans les dernières semaines en raison d'une possible hémorragie fœtale : on administre alors de l'héparine.","s":5},{"q":"Quel est l'effet de la cimétidine sur la warfarine ?","o":["Elle diminue sa métabolisation, augmentant donc son effet","Elle augmente sa métabolisation","Elle n'a aucun effet","Elle l'inactive"],"r":0,"e":"La cimétidine diminue la métabolisation de la warfarine, ce qui augmente son effet ; la carbamazépine, à l'inverse, l'augmente.","s":5},{"q":"Comment le cours définit-il l'asthme ?","o":["Un bronchospasme isolé","Une maladie inflammatoire chronique des voies aériennes avec hyperréactivité bronchique et bronchospasme","Une infection bronchique récidivante","Une allergie respiratoire aiguë"],"r":1,"e":"L'asthme est considéré comme une maladie inflammatoire chronique des voies aériennes à laquelle s'associent l'hyperréactivité bronchique et le bronchospasme.","s":5},{"q":"Quelle est la voie d'administration de choix dans le traitement de l'asthme ?","o":["La voie orale","La voie inhalatoire","La voie intraveineuse","La voie sous-cutanée"],"r":1,"e":"La voie d'administration de choix dans le traitement de l'asthme est la voie inhalatoire.","s":5},{"q":"Quels corticostéroïdes inhalés le cours cite-t-il ?","o":["Béclométasone, budésonide et fluticasone","Prednisolone, dexaméthasone et hydrocortisone","Bétaméthasone et déflazacort","Méthylprednisolone uniquement"],"r":0,"e":"La voie inhalatoire utilise la béclométasone, le budésonide et la fluticasone, médicaments d'efficacité superposable dans le traitement de l'asthme.","s":5},{"q":"Quels sont les mécanismes de la théophylline ?","o":["Inhibition non sélective des phosphodiestérases et antagonisme des récepteurs de l'adénosine","Agonisme béta-2 sélectif","Blocage des récepteurs muscariniques","Inhibition des leucotriènes"],"r":0,"e":"La théophylline et l'aminophylline sont des composés xanthiques dont le mécanisme comprend l'inhibition non sélective des phosphodiestérases et l'antagonisme des récepteurs de l'adénosine (+++).","s":5},{"q":"Quel principe le cours énonce-t-il à propos de la toux ?","o":["Elle doit toujours être supprimée","Elle ne doit pas, par principe, être traitée comme un symptôme : il faut d'abord chercher la cause","Elle doit être traitée par antibiotiques","Elle est toujours d'origine allergique"],"r":1,"e":"La toux est en général la conséquence de l'irritation des voies aériennes ; elle ne doit pas, par principe, être traitée comme un symptôme : il faut d'abord chercher la cause et tenter de l'éliminer.","s":5},{"q":"Quels mucolytiques le cours cite-t-il ?","o":["L'acétylcystéine, la bromhexine et la carbocistéine","La codéine et le clobutinol","La diméticone et le charbon activé","Le lopéramide et le psyllium"],"r":0,"e":"Les mucolytiques comme l'acétylcystéine, la bromhexine et la carbocistéine agissent par modification des propriétés rhéologiques du mucus.","s":5},{"q":"Dans quel cas les antitussifs sont-ils contre-indiqués ?","o":["Dans la toux sèche et fatigante","Dans la toux productive, l'insuffisance respiratoire avec rétention de sécrétions, et chez l'enfant de moins d'1 an","Chez l'adulte de plus de 65 ans","En cas d'allergie saisonnière"],"r":1,"e":"Les antitussifs ne sont pas indiqués dans la toux productive associée à une insuffisance respiratoire et à une rétention de sécrétions, et sont contre-indiqués chez les enfants de moins d'1 an.","s":5},{"q":"Quels trois médiateurs régulent la sécrétion de HCl ?","o":["Histamine, acétylcholine et gastrine","Sérotonine, dopamine et GABA","Insuline, glucagon et somatostatine","Adrénaline, noradrénaline et cortisol"],"r":0,"e":"La sécrétion de HCl par les cellules pariétales est régulée par l'histamine, l'acétylcholine et la gastrine, dont l'activation aboutit à l'activation de la pompe à protons K+/H+ ATPase.","s":5},{"q":"Quel est le mécanisme du sucralfate ?","o":["Il inhibe la pompe à protons","Il a une capacité antiacide minime mais recouvre le cratère ulcéreux, protégeant contre le binôme acide-pepsine","Il bloque les récepteurs H2","Il neutralise chimiquement l'acide"],"r":1,"e":"Le sucralfate a une capacité antiacide minime mais un effet protecteur contre le binôme acide-pepsine en recouvrant le cratère ulcéreux ; il se dissocie à pH 3-4 en composé chargé négativement qui se lie aux protéines de l'ulcère.","s":5},{"q":"Quel est l'élément FONDAMENTAL du traitement de la diarrhée selon le cours ?","o":["Le lopéramide","L'hydratation","Le charbon activé","La diméticone"],"r":1,"e":"Après avoir cherché la cause, l'hydratation est présentée comme fondamentale ; le lopéramide diminue la motilité et, en excès, cause une constipation ; les antimotilité sont contre-indiqués chez les jeunes enfants.","s":5},{"q":"Les cinq classes d'antihypertenseurs distinguées par le cours comprennent :","o":["Diurétiques, modificateurs de l'axe rénine-angiotensine, bloqueurs calciques, dépresseurs adrénergiques et vasodilatateurs directs","Diurétiques, bêtabloquants, statines, anticoagulants et nitrates","IEC, AINS, corticoïdes, diurétiques et nitrates","Nitrates, bloqueurs calciques, mucolytiques, IEC et sartans"],"r":0,"e":"Les dépresseurs de l'activité adrénergique regroupent eux-mêmes les bloqueurs alpha, les bloqueurs bêta et les agonistes alpha-2 centraux.","s":5},{"q":"Les antagonistes des récepteurs de l'angiotensine se distinguent des IEC parce qu'ils agissent :","o":["Sur l'enzyme de conversion","Au niveau du récepteur","Sur l'aldostérone directement","Sur la rénine"],"r":1,"e":"Les IEC bloquent la transformation de l'angiotensine I en angiotensine II ; les sartans laissent cette conversion se faire mais empêchent l'effet au récepteur.","s":5},{"q":"Pour le kinésithérapeute, le risque pratique lié aux IEC est :","o":["Une hypotension orthostatique au lever et en fin de séance","Une hyperglycémie","Une bronchoconstriction","Une tachycardie"],"r":0,"e":"Le problème des IEC est l'hypotension, d'où un ajustement graduel de la dose. Le lever après une séance au sol est un moment particulièrement exposé.","s":5},{"q":"Le blocage du récepteur β2 par un bêtabloquant non sélectif peut provoquer une hypoglycémie parce qu'il :","o":["Augmente la sécrétion d'insuline","Bloque l'effet β2 sur le glucagon","Réduit l'absorption du glucose","Stimule la glycogénogenèse"],"r":1,"e":"Ce même blocage β2 supprime la bronchodilatation et peut déclencher une crise d'asthme. Les bêtabloquants lipophiles à courte demi-vie sont les plus en cause.","s":5},{"q":"Le traitement de l'angine de poitrine repose sur deux stratégies :","o":["Réduire le besoin en oxygène du myocarde ou augmenter le débit sanguin dans les zones ischémiées","Anticoaguler ou fibrinolyser","Dilater les veines ou contracter les artères","Réduire le cholestérol ou la pression"],"r":0,"e":"La première passe par les bêtabloquants, la seconde par les nitrates, les bloqueurs calciques et l'allongement du temps de diastole.","s":5},{"q":"Les vénotropes sont majoritairement, sur le plan chimique :","o":["Des dérivés nitrés","Des flavonoïdes ou substances apparentées, comme la diosmine","Des xanthines","Des statines"],"r":1,"e":"Les bioflavonoïdes diminuent la perméabilité capillaire. Le cours insiste : dans l'insuffisance veineuse, la thérapeutique non pharmacologique est fondamentale.","s":5},{"q":"Dans l'insuffisance veineuse, le cours souligne que le traitement fondamental est :","o":["Pharmacologique","Non pharmacologique, terrain direct du kinésithérapeute","Chirurgical","Diététique"],"r":1,"e":"Drainage, compression, mobilisation de la pompe du mollet et activité physique : ce sont les moyens les plus efficaces, les vénotropes restant un appoint.","s":5},{"q":"L'enzyme inhibée par les statines est :","o":["La lipoprotéine lipase","L'HMG-CoA réductase, enzyme limitante de la voie du mévalonate","L'anhydrase carbonique","La cyclooxygénase"],"r":1,"e":"En bloquant l'étape limitante de la synthèse hépatique du cholestérol, elles font baisser le LDL, augmenter le HDL et diminuer les triglycérides.","s":5},{"q":"L'atorvastatine se caractérise par une inhibition :","o":["Réversible","Irréversible","Compétitive uniquement","Allostérique"],"r":1,"e":"La simvastatine est l'autre molécule citée. Le caractère irréversible implique que la récupération dépende de la synthèse de nouvelles enzymes.","s":5},{"q":"Les interactions des statines concernent principalement :","o":["Les inhibiteurs du cytochrome P450 : érythromycine, ciclosporine, acide nicotinique, antirétroviraux, antifongiques azolés","Les antiacides","Les diurétiques","Les anticoagulants"],"r":0,"e":"Ces inhibiteurs ralentissent le métabolisme de la statine, dont la concentration s'élève — et avec elle le risque de myopathie.","s":5},{"q":"Devant des myalgies diffuses chez un patient sous statine, le cours recommande :","o":["De conclure à une origine mécanique","De ne pas conclure trop vite : il peut s'agir d'une myopathie médicamenteuse, à signaler au médecin","D'augmenter les étirements","D'arrêter la kinésithérapie"],"r":1,"e":"L'élévation de la créatine kinase, les crampes et l'asthénie sont des effets indésirables caractéristiques de cette classe.","s":5},{"q":"La cible de cholestérol total chez un patient à risque est :","o":["Moins de 190 mg/dl","Moins de 175 mg/dl","Moins de 150 mg/dl","Moins de 115 mg/dl"],"r":1,"e":"Les autres cibles : cholestérol total inférieur à 190 mg/dl en général, LDL inférieur à 115 mg/dl (100 à risque), triglycérides inférieurs à 150 mg/dl.","s":5},{"q":"L'ézétimibe associé à une statine agit en :","o":["Inhibant l'HMG-CoA réductase","Réduisant l'absorption du cholestérol dans l'intestin","Augmentant l'excrétion biliaire","Bloquant la lipase pancréatique"],"r":1,"e":"Les deux mécanismes sont complémentaires : l'un réduit la production hépatique, l'autre l'apport intestinal.","s":5},{"q":"Parmi les anticoagulants oraux, le cours cite :","o":["L'héparine et l'énoxaparine","La warfarine et le rivaroxaban","L'aspirine et le clopidogrel","L'altéplase et la streptokinase"],"r":1,"e":"Les héparines s'administrent par voie parentérale. Les fibrinolytiques, activateurs du plasminogène, servent à dissoudre un réseau de fibrine déjà constitué.","s":5},{"q":"La warfarine bloque :","o":["L'agrégation plaquettaire","La carboxylation du glutamate des précurseurs des facteurs de coagulation, dépendante de la vitamine K","La conversion du fibrinogène en fibrine","La production de thrombine par le foie"],"r":1,"e":"C'est pourquoi tout apport variable en vitamine K modifie l'effet, et pourquoi la surveillance repose sur l'INR.","s":5},{"q":"La carbamazépine modifie l'effet de la warfarine en :","o":["Diminuant sa métabolisation, donc en augmentant son effet","Augmentant sa métabolisation, donc en diminuant son effet","Bloquant son absorption","Déplaçant sa liaison protéique"],"r":1,"e":"La cimétidine fait l'inverse : elle diminue la métabolisation et augmente l'effet anticoagulant, donc le risque hémorragique.","s":5},{"q":"L'association warfarine + AINS entraîne :","o":["Une potentialisation de l'action anticoagulante","Une diminution de l'effet","Aucune interaction","Une inactivation de l'AINS"],"r":0,"e":"Les antiagrégants plaquettaires comme l'acide acétylsalicylique augmentent également le risque hémorragique, par un mécanisme différent mais additif.","s":5},{"q":"En fin de grossesse, la warfarine est contre-indiquée en raison :","o":["De son effet tératogène","Du risque d'hémorragie fœtale","D'un effet abortif","D'une inefficacité"],"r":1,"e":"Au premier trimestre, c'est la tératogénicité qui la contre-indique. Dans les deux cas, on lui substitue l'héparine, qui ne franchit pas le placenta.","s":5},{"q":"Les trois approches du traitement de l'asthme sont :","o":["Suppression du facteur causal, thérapeutique anti-inflammatoire et thérapeutique bronchodilatatrice","Antibiotique, corticoïde et kinésithérapie","Oxygène, bronchodilatateur et antitussif","Vaccination, mucolytique et antihistaminique"],"r":0,"e":"La suppression du facteur causal comprend la prévention de l'exposition aux déclencheurs et la vaccination. La voie inhalatoire est la voie de choix.","s":5},{"q":"Les corticostéroïdes dans l'asthme sont :","o":["Uniquement bronchodilatateurs","Anti-inflammatoires et indirectement bronchodilatateurs","Sans effet sur l'inflammation","Réservés à la voie orale"],"r":1,"e":"La voie parentérale est réservée aux situations graves ; la voie inhalatoire est fondamentale en traitement d'entretien.","s":5}]};
